import importlib, importlib.metadata, importlib.util, re, subprocess, sys


# ScriptRequirements: What the script needs installed, as (module to import, requirement for pip)
ScriptRequirements = [('numpy', 'numpy>=1.26.4'), ('FixRaidenBoss2', 'FixRaidenBoss2>=5.0.0')]


def scriptVersionTuple(version: str):
    match = re.match(r"\d+(\.\d+)*", version)
    return tuple(int(part) for part in match.group(0).split(".")) if (match is not None) else ()


def installScriptRequirements():
    missing = []
    for module, requirement in ScriptRequirements:
        if (importlib.util.find_spec(module) is None):
            missing.append(requirement)
            continue

        # a package reachable without pip (eg. through PYTHONPATH) has no version to read, and is trusted
        try:
            installed = importlib.metadata.version(module)
        except importlib.metadata.PackageNotFoundError:
            continue

        minimum = requirement.partition(">=")[2]
        if (minimum and scriptVersionTuple(installed) < scriptVersionTuple(minimum)):
            missing.append(requirement)

    if (not missing):
        return

    print(f"Installing what this script needs: {', '.join(missing)}...")
    try:
        subprocess.check_call([sys.executable, "-m", "pip", "install"] + missing)
    except (OSError, subprocess.CalledProcessError):
        # quoted, since a shell reads the '>' of a requirement as a redirection
        command = " ".join(f'"{part}"' for part in [sys.executable, "-m", "pip", "install"] + missing)
        print(f"Could not install {', '.join(missing)}. Install them yourself with: {command}")
        sys.exit(1)

    importlib.invalidate_caches()


installScriptRequirements()


