class DownloadFailed(Error):
    """
    Exception when a file of a download folder cannot be downloaded

    Parameters
    ----------
    url: :class:`str`
        The address of the file

    reason: :class:`str`
        Why the download failed

    Attributes
    ----------
    url: :class:`str`
        The address of the file
    """

    def __init__(self, url: str, reason: str):
        super().__init__(f"Could not download {url}: {reason}")
        self.url = url


class ModDownload():
    """
    Class for one version of a character's download folder: which files it has, and which repository each
    one is kept in

    Parameters
    ----------
    loader: :class:`ModLoaders`
        The mod loader the character's mods are for

    name: :class:`str`
        The name of the character's folder (eg. ``Yelan``)

    version: :class:`str`
        The name of the version folder (eg. ``4_0``)

    prefix: :class:`str`
        What the names of the folder's files start with. It is usually :attr:`name`, but not always (the ``Raiden`` folder's files start with ``RaidenShogun``)

    files: Dict[:class:`str`, :class:`ModDownloadRepos`]
        The repository each file is kept in, by file name

    Attributes
    ----------
    loader: :class:`ModLoaders`
        The mod loader the character's mods are for

    name: :class:`str`
        The name of the character's folder (eg. ``Yelan``)

    version: :class:`str`
        The name of the version folder (eg. ``4_0``)

    prefix: :class:`str`
        What the names of the folder's files start with

    files: Dict[:class:`str`, :class:`ModDownloadRepos`]
        The repository each file is kept in, by file name

    folder: Optional[:class:`str`]
        Where the files were downloaded to, or ``None`` if they have not been
    """

    def __init__(self, loader: ModLoaders, name: str, version: str, prefix: str, files: Dict[str, ModDownloadRepos]):
        self.loader = loader
        self.name = name
        self.version = version
        self.prefix = prefix
        self.files = files
        self.folder = None


#: What a Git LFS pointer file starts with
LfsPointerHeader = b"version https://git-lfs.github.com/spec/v1"

#: The largest a Git LFS pointer file can be, in bytes (a real one is about 130)
LfsPointerMaxSize = 1024


class ModDownloader(Model):
    """
    Finds and downloads characters' download folders. Each file is taken from the first of
    :class:`ModDownloadRepos` that keeps it: Anime Game Remap's repository, then this library's

    .. note::
        Files are downloaded with Anime Game Remap's ``FixRaidenBoss2.FileDownload``, which retries a
        failed download and follows GitHub's redirects.

    Parameters
    ----------
    localFolders: Optional[Dict[:class:`ModDownloadRepos`, :class:`str`]]
        Local copies of the repositories' ``Data/Mod Downloads`` folders (eg. a clone of Anime Game Remap). A file found in its repository's local folder is copied from there instead of downloaded. If this value is ``None``, every file is downloaded :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    proxy: Optional[:class:`str`]
        The proxy to download through. If this value is ``None``, no proxy is used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    logger: Optional[:class:`BaseLogger`]
        Where to report what is done. If this value is ``None``, nothing is reported :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Attributes
    ----------
    localFolders: Dict[:class:`ModDownloadRepos`, :class:`str`]
        Local copies of the repositories' ``Data/Mod Downloads`` folders

    proxy: Optional[:class:`str`]
        The proxy to download through
    """

    def __init__(self, localFolders: Optional[Dict[ModDownloadRepos, str]] = None, proxy: Optional[str] = None, logger: Optional[BaseLogger] = None):
        super().__init__(logger = logger)
        self.localFolders = {} if (localFolders is None) else localFolders
        self.proxy = proxy

    @classmethod
    def getCharacters(cls, loader: ModLoaders) -> List[str]:
        """
        Retrieves the characters that have a download folder an identity mod can be generated from

        Parameters
        ----------
        loader: :class:`ModLoaders`
            The mod loader

        Returns
        -------
        List[:class:`str`]
            The names of the characters' folders, in alphabetical order
        """

        return sorted(ModDownloadData.get(ModDownloadGameFolders[loader], {}), key = str.lower)

    @classmethod
    def getName(cls, loader: ModLoaders, name: str) -> str:
        """
        Retrieves the name of a character's folder, from its name or another name it is known by (eg. ``KamisatoAyaka`` for ``Ayaka``), in any case

        Parameters
        ----------
        loader: :class:`ModLoaders`
            The mod loader

        name: :class:`str`
            The character's name

        Raises
        ------
        :class:`Error`
            If no character has that name

        Returns
        -------
        :class:`str`
            The name of the character's folder
        """

        game = ModDownloadGameFolders[loader]
        characters = ModDownloadData.get(game, {})
        if (name in characters):
            return name

        # an alias may name a character with no listed folder (eg. one whose asset folder cannot be built)
        aliases = {alias.lower(): folder for alias, folder in ModDownloadAliases.get(game, {}).items() if folder in characters}
        folders = {folder.lower(): folder for folder in characters}
        result = aliases.get(name.lower(), folders.get(name.lower()))
        if (result is None):
            raise Error(f"no {game} character called '{name}' has a download folder")
        return result

    @classmethod
    def getVersions(cls, loader: ModLoaders, name: str) -> List[str]:
        """
        Retrieves the versions of a character's download folder

        Parameters
        ----------
        loader: :class:`ModLoaders`
            The mod loader

        name: :class:`str`
            The character's name

        Raises
        ------
        :class:`Error`
            If no character has that name

        Returns
        -------
        List[:class:`str`]
            The version folders, oldest first
        """

        folder = cls.getName(loader, name)
        return sorted(ModDownloadData[ModDownloadGameFolders[loader]][folder], key = VersionTools.parse)

    @classmethod
    def find(cls, loader: ModLoaders, name: str, version: Optional[str] = None) -> ModDownload:
        """
        Finds a version of a character's download folder

        Parameters
        ----------
        loader: :class:`ModLoaders`
            The mod loader

        name: :class:`str`
            The character's name

        version: Optional[:class:`str`]
            The game version wanted (eg. ``4.0`` or ``4_0``). The newest folder not newer than it is chosen, or the oldest if every folder is newer (see :meth:`VersionTools.getClosest`). If this value is ``None``, the newest folder is chosen :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        Raises
        ------
        :class:`Error`
            If no character has that name, or ``version`` is not a game version

        Returns
        -------
        :class:`ModDownload`
            The download folder, not downloaded yet
        """

        folder = cls.getName(loader, name)
        versions = ModDownloadData[ModDownloadGameFolders[loader]][folder]
        chosen = VersionTools.getClosest(versions, version)
        prefix, files = versions[chosen]
        return ModDownload(loader, folder, chosen, prefix, {fileName: ModDownloadRepos[repo] for fileName, repo in files.items()})

    @classmethod
    def getUrl(cls, download: ModDownload, fileName: str) -> str:
        """
        Retrieves the address of a file of a download folder

        Parameters
        ----------
        download: :class:`ModDownload`
            The download folder

        fileName: :class:`str`
            The name of the file

        Returns
        -------
        :class:`str`
            The address
        """

        repo = download.files[fileName]
        path = "/".join(quote(part) for part in (ModDownloadGameFolders[download.loader], download.name, download.version, fileName))
        return f"{repo.value}/{path}"

    @classmethod
    def isLfsPointer(cls, path: str) -> bool:
        """
        Whether a file is a Git LFS pointer: the small text file Git keeps in place of a file stored in Git LFS

        Parameters
        ----------
        path: :class:`str`
            The path to the file

        Returns
        -------
        :class:`bool`
            Whether the file is a Git LFS pointer
        """

        if (os.path.getsize(path) > LfsPointerMaxSize):
            return False
        with open(path, "rb") as f:
            return f.read(len(LfsPointerHeader)) == LfsPointerHeader

    def _getLocalPath(self, download: ModDownload, fileName: str) -> Optional[str]:
        root = self.localFolders.get(download.files[fileName])
        if (root is None):
            return None

        path = os.path.join(root, ModDownloadGameFolders[download.loader], download.name, download.version, fileName)
        return path if (os.path.isfile(path)) else None

    def _downloadFile(self, url: str, fileName: str, folder: str):
        try:
            FRB.FileDownload(url, fileName, cache = False).download(folder, self.proxy)
        except Exception as e:
            raise DownloadFailed(url, str(e)) from None

    def download(self, download: ModDownload, folder: str) -> ModDownload:
        """
        Downloads a download folder's files

        Parameters
        ----------
        download: :class:`ModDownload`
            The download folder, from :meth:`find`

        folder: :class:`str`
            The folder to put the files in. It is created if it does not exist

        Raises
        ------
        :class:`DownloadFailed`
            If a file cannot be downloaded, or what arrives is a Git LFS pointer instead of the file

        Returns
        -------
        :class:`ModDownload`
            ``download``, with its :attr:`ModDownload.folder` set to ``folder``
        """

        os.makedirs(folder, exist_ok = True)
        self.print("log", f"Getting {len(download.files)} files of {download.name}'s {download.version} download folder")
        for fileName in sorted(download.files):
            localPath = self._getLocalPath(download, fileName)
            if (localPath is not None):
                source = localPath
                shutil.copyfile(localPath, os.path.join(folder, fileName))
            else:
                source = self.getUrl(download, fileName)
                self.print("log", f"Downloading {source}")
                self._downloadFile(source, fileName, folder)

            # the download folders' binaries are kept in Git LFS: a clone made without git-lfs, or an address that
            #   bypasses LFS, gives the small pointer file instead of the file, which no generator could read
            if (not os.path.isfile(os.path.join(folder, fileName))):
                raise DownloadFailed(source, "the file did not arrive")
            if (self.isLfsPointer(os.path.join(folder, fileName))):
                raise DownloadFailed(source, "it is a Git LFS pointer, not the file (a clone needs 'git lfs install' then 'git lfs pull')")

        download.folder = folder
        return download


class GIMIBuffers(Enum):
    """
    The vertex buffers of one component of a GIMI mod, in the order GIMI lays a vertex out. Each one is
    written to ``<name><component><buffer>.buf``

    Attributes
    ----------
    Position: :class:`str`
        The ``POSITION``, ``NORMAL`` and ``TANGENT`` of the vertices

    Blend: :class:`str`
        The ``BLENDWEIGHT(S)`` and ``BLENDINDICES`` of the vertices

    Texcoord: :class:`str`
        The ``COLOR`` and ``TEXCOORD`` (``TEXCOORD1``, ...) of the vertices
    """

    Position = "Position"
    Blend = "Blend"
    Texcoord = "Texcoord"


#: The buffer each element of a dumped vertex belongs to, by its semantic name
GIMISemanticBuffers: Dict[str, GIMIBuffers] = {
    "POSITION": GIMIBuffers.Position, "NORMAL": GIMIBuffers.Position, "TANGENT": GIMIBuffers.Position,
    "BLENDWEIGHT": GIMIBuffers.Blend, "BLENDWEIGHTS": GIMIBuffers.Blend, "BLENDINDICES": GIMIBuffers.Blend,
    "COLOR": GIMIBuffers.Texcoord, "TEXCOORD": GIMIBuffers.Texcoord
}

#: The number of bytes per vertex GIMI fixes for a buffer. The Texcoord buffer's is not fixed: it is 20 with a second UV set and 12 without, and can differ between the components of one character
GIMIFixedStrides: Dict[GIMIBuffers, int] = {GIMIBuffers.Position: 40, GIMIBuffers.Blend: 32}

#: What the name of a download folder's copy of the asset folder's ``hash.json`` ends with: ``<prefix>Hash.json``
GIMIHashFileSuffix = "Hash.json"


class GIMITextureLayouts(Enum):
    """
    The two layouts a GIMI mod binds an object's textures in, chosen by whether the object's shader reads a
    normal map. Each value is the (register, texture kind) pairs of the layout, and the command list of
    ``ORFix`` that moves the textures to the registers the shader actually reads

    Attributes
    ----------
    NormalMap: Tuple[Tuple[Tuple[:class:`str`, :class:`str`], ...], :class:`str`]
        ``ps-t0`` normal map, ``ps-t1`` diffuse and ``ps-t2`` light map, fixed by ``ORFix``

    Plain: Tuple[Tuple[Tuple[:class:`str`, :class:`str`], ...], :class:`str`]
        ``ps-t0`` diffuse and ``ps-t1`` light map, fixed by ``NNFix``
    """

    NormalMap = ((("ps-t0", "NormalMap"), ("ps-t1", "Diffuse"), ("ps-t2", "LightMap")), "CommandList\\global\\ORFix\\ORFix")
    Plain = ((("ps-t0", "Diffuse"), ("ps-t1", "LightMap")), "CommandList\\global\\ORFix\\NNFix")

    @property
    def registers(self) -> Tuple[Tuple[str, str], ...]:
        """
        The (register, texture kind) pairs of the layout

        :getter: Retrieves the registers
        :type: Tuple[Tuple[:class:`str`, :class:`str`], ...]
        """

        return self.value[0]

    @property
    def fixCommand(self) -> str:
        """
        The command list that moves the layout's textures to the registers the shader reads

        :getter: Retrieves the command list
        :type: :class:`str`
        """

        return self.value[1]


class GIMIComponent():
    """
    Class for one component of a GI character's GIMI identity mod: one skinned mesh with its
    own vertex buffers, index buffer and objects (eg. YelanTranquil's Body, Bang and Eye). An older
    character is a single component whose name is the empty string

    Parameters
    ----------
    name: :class:`str`
        The name of the component (its ``component_name`` in ``hash.json``)

    entry: Dict[:class:`str`, Any]
        The component's entry in the asset folder's ``hash.json``

    vertexCount: :class:`int`
        The number of vertices of the component

    buffers: Dict[:class:`GIMIBuffers`, :class:`bytes`]
        The contents of each vertex buffer

    strides: Dict[:class:`GIMIBuffers`, :class:`int`]
        The number of bytes of one vertex in each vertex buffer

    indices: Dict[:class:`str`, numpy.ndarray]
        The indices of each object, as ``uint32``

    textures: Dict[:class:`str`, Dict[:class:`str`, :class:`str`]]
        For each object with textures of its own, the file name in the mod of each kind of texture (eg. ``Diffuse``)

    Attributes
    ----------
    name: :class:`str`
        The name of the component (its ``component_name`` in ``hash.json``)

    entry: Dict[:class:`str`, Any]
        The component's entry in the asset folder's ``hash.json``

    vertexCount: :class:`int`
        The number of vertices of the component

    buffers: Dict[:class:`GIMIBuffers`, :class:`bytes`]
        The contents of each vertex buffer

    strides: Dict[:class:`GIMIBuffers`, :class:`int`]
        The number of bytes of one vertex in each vertex buffer

    indices: Dict[:class:`str`, numpy.ndarray]
        The indices of each object, as ``uint32``

    textures: Dict[:class:`str`, Dict[:class:`str`, :class:`str`]]
        For each object with textures of its own, the file name in the mod of each kind of texture (eg. ``Diffuse``)

    boundTextures: Dict[:class:`str`, Tuple[:class:`str`, :class:`str`, Dict[:class:`str`, :class:`str`]]]
        For each object, the component and object whose textures it binds and the file name of each kind of texture bound. An object with no textures to bind has an empty dictionary of textures
    """

    def __init__(self, name: str, entry: Dict[str, Any], vertexCount: int, buffers: Dict[GIMIBuffers, bytes],
                 strides: Dict[GIMIBuffers, int], indices: Dict[str, np.ndarray], textures: Dict[str, Dict[str, str]]):
        self.name = name
        self.entry = entry
        self.vertexCount = vertexCount
        self.buffers = buffers
        self.strides = strides
        self.indices = indices
        self.textures = textures
        self.boundTextures: Dict[str, Tuple[str, str, Dict[str, str]]] = {}

    @property
    def objects(self) -> List[str]:
        """
        The names of the component's objects (eg. ``Head``, ``Body``), in order

        :getter: Retrieves the objects
        :type: List[:class:`str`]
        """

        return list(self.entry["object_classifications"])

    @property
    def firstIndices(self) -> List[int]:
        """
        Where each object's indices start in the game's index buffer, in the order of :attr:`objects`

        :getter: Retrieves the first indices
        :type: List[:class:`int`]
        """

        return list(self.entry["object_indexes"])


class GIMIIniBuilder():
    """
    Writes the ``.ini`` of a GIMI identity mod, in the shape GIMI generates

    Parameters
    ----------
    name: :class:`str`
        The name of the character in the mod's files and sections

    components: List[:class:`GIMIComponent`]
        The skinned components of the character, with their bound textures

    source: :class:`str`
        What the mod was generated from, as the end of the sentence "the game's own model out of ..." (eg. ``its asset folder (Yelan)``)

    faceDiffuse: Optional[:class:`str`]
        The file name in the mod of the face's diffuse texture, or ``None`` if the mod has none :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    faceHash: Optional[:class:`str`]
        The hash the game binds the face's diffuse texture under, or ``None`` if it is not known :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    faceRegister: :class:`str`
        The register the face's diffuse texture is bound to :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``"ps-t0"``

    includeFix: :class:`bool`
        Whether an object that binds textures runs the ``ORFix`` command list of its layout :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``True``

    Attributes
    ----------
    name: :class:`str`
        The name of the character in the mod's files and sections

    components: List[:class:`GIMIComponent`]
        The skinned components of the character, with their bound textures

    source: :class:`str`
        What the mod was generated from, as the end of the sentence "the game's own model out of ..." (eg. ``its asset folder (Yelan)``)

    faceDiffuse: Optional[:class:`str`]
        The file name in the mod of the face's diffuse texture, or ``None`` if the mod has none

    faceHash: Optional[:class:`str`]
        The hash the game binds the face's diffuse texture under, or ``None`` if it is not known

    faceRegister: :class:`str`
        The register the face's diffuse texture is bound to

    includeFix: :class:`bool`
        Whether an object that binds textures runs the ``ORFix`` command list of its layout
    """

    def __init__(self, name: str, components: List[GIMIComponent], source: str, faceDiffuse: Optional[str] = None,
                 faceHash: Optional[str] = None, faceRegister: str = "ps-t0", includeFix: bool = True):
        self.name = name
        self.components = components
        self.source = source
        self.faceDiffuse = faceDiffuse
        self.faceHash = faceHash
        self.faceRegister = faceRegister
        self.includeFix = includeFix

    def build(self) -> str:
        """
        Writes the text of the ``.ini``

        Returns
        -------
        :class:`str`
            The text, with ``\\n`` line endings
        """

        name = self.name
        L = [f"; {name}", "", "; Constants -------------------------", "", "; Overrides -------------------------", ""]

        for component in self.components:
            comp = component.name
            entry = component.entry
            L += [f"[TextureOverride{name}{comp}Position]", f"hash = {entry['position_vb']}", f"vb0 = Resource{name}{comp}Position", ""]
            L += [f"[TextureOverride{name}{comp}Blend]", f"hash = {entry['blend_vb']}", f"vb1 = Resource{name}{comp}Blend", "handling = skip", f"draw = {component.vertexCount},0", ""]
            L += [f"[TextureOverride{name}{comp}Texcoord]", f"hash = {entry['texcoord_vb']}", f"vb1 = Resource{name}{comp}Texcoord", ""]
            L += [f"[TextureOverride{name}{comp}VertexLimitRaise]", f"hash = {entry['draw_vb']}", ""]
            L += [f"[TextureOverride{name}{comp}IB]", f"hash = {entry['ib']}", "handling = skip", "drawindexed = auto", ""]

            for obj, first in zip(component.objects, component.firstIndices):
                L += [f"[TextureOverride{name}{comp}{obj}]", f"hash = {entry['ib']}", f"match_first_index = {first}", f"ib = Resource{name}{comp}{obj}IB"]
                sourceComponent, sourceObj, bound = component.boundTextures[obj]
                layout = GIMITextureLayouts.NormalMap if ("NormalMap" in bound) else GIMITextureLayouts.Plain

                for register, kind in layout.registers:
                    if (kind in bound):
                        L.append(f"{register} = Resource{name}{sourceComponent}{sourceObj}{kind}")

                # no textures to bind, so no fix call either: ORFix / NNFix re-slot whatever is bound,
                #   and the game's own textures are already in the registers the shader wants
                if (bound and self.includeFix):
                    L.append(f"run = {layout.fixCommand}")
                L.append("")

        if (self.faceDiffuse and self.faceHash):
            L += [f"[TextureOverride{name}FaceHeadDiffuse]", f"hash = {self.faceHash}", f"{self.faceRegister} = Resource{name}FaceHeadDiffuse", ""]

        L += ["", "; CommandList -----------------------", "", "; Resources -------------------------", ""]
        for component in self.components:
            for buffer in GIMIBuffers:
                L += [f"[Resource{name}{component.name}{buffer.value}]", "type = Buffer", f"stride = {component.strides[buffer]}", f"filename = {name}{component.name}{buffer.value}.buf", ""]

        for component in self.components:
            for obj in component.objects:
                L += [f"[Resource{name}{component.name}{obj}IB]", "type = Buffer", "format = DXGI_FORMAT_R32_UINT", f"filename = {name}{component.name}{obj}.ib", ""]

        for component in self.components:
            for obj in component.objects:
                for kind, fileName in component.textures.get(obj, {}).items():
                    L += [f"[Resource{name}{component.name}{obj}{kind}]", f"filename = {fileName}", ""]

        if (self.faceDiffuse):
            L += [f"[Resource{name}FaceHeadDiffuse]", f"filename = {self.faceDiffuse}", ""]

        L += ["", f"; the identity mod of {name}: the game's own model out of {self.source}, built by AGIDMGen", ""]
        return "\n".join(L)


class FileEncodings(Enum):
    """
    The text encodings used when reading and writing the files of a mod

    Attributes
    ----------
    UTF8: :class:`str`
        The `utf-8` encoding

    Latin1: :class:`str`
        The `latin1` encoding
    """

    UTF8 = "utf-8"
    Latin1 = "latin1"


#: The encoding a ``.ini`` file is written in
IniFileEncoding = FileEncodings.UTF8.value
#: The encodings tried, in order, when reading a text file
ReadEncodings = [IniFileEncoding, FileEncodings.Latin1.value]


class BadAssetData(Error):
    """
    Exception when a character's asset folder is missing a file, or holds data that does not agree with
    itself (eg. a buffer whose size does not match the vertex count its metadata declares)

    Parameters
    ----------
    message: :class:`str`
        What is missing or wrong in the asset folder
    """

    def __init__(self, message: str):
        super().__init__(message)


class DumpDataKinds(Enum):
    """
    The kinds of value one channel of a buffer element can hold, as named by the suffix of its DXGI format

    Attributes
    ----------
    Float: :class:`str`
        A floating point number (``FLOAT``)

    SignedInt: :class:`str`
        A signed integer (``SINT``)

    UnsignedInt: :class:`str`
        An unsigned integer (``UINT``)

    Unorm: :class:`str`
        An unsigned number from 0 to 1, stored as an unsigned integer scaled to its largest value (``UNORM``)
    """

    Float = "FLOAT"
    SignedInt = "SINT"
    UnsignedInt = "UINT"
    Unorm = "UNORM"


# The grammar of C++'s std::from_chars, which is how AG Remap's dump readers (FixRaidenBoss2's
#   VbFile / IbFile.readDumpStr) parse every value: the LONGEST valid prefix of the text is the value,
#   and text with no valid prefix is 0. Unlike Python's int() / float(), it takes no leading '+', no
#   '_' digit separators, no hex, and only ASCII digits -- so "+1" is 0, "1_0" is 1 and "12abc" is 12.
_SignedIntPrefix = re.compile(r"-?[0-9]+")
_UnsignedIntPrefix = re.compile(r"[0-9]+")
_DoublePrefix = re.compile(r"-?(?:(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|(?i:inf(?:inity)?)|(?i:nan(?:\([0-9A-Za-z_]*\))?))")

_LongLongMin = -(1 << 63)
_LongLongMax = (1 << 63) - 1
_UnsignedLongLongMax = (1 << 64) - 1

# the characters a dump value is trimmed of on both sides
DumpValueWhitespace = " \t\r"


class DumpValueTools():
    """
    Tools for parsing the text values of a 3DMigoto buffer dump, the way AG Remap's dump readers parse them

    .. note::
        A value is read from the longest valid prefix of its text, and text with no valid prefix (or a
        number too large for its type) is read as 0, rather than raising an error.
    """

    @classmethod
    def parseSignedInt(cls, txt: str) -> int:
        """
        Parses a signed integer

        Parameters
        ----------
        txt: :class:`str`
            The text of the value

        Returns
        -------
        :class:`int`
            The value, or 0 if the text has no valid prefix or the value does not fit a 64-bit signed integer
        """

        match = _SignedIntPrefix.match(txt.strip(DumpValueWhitespace))
        if (match is None):
            return 0

        value = int(match.group())
        return value if (_LongLongMin <= value <= _LongLongMax) else 0

    @classmethod
    def parseUnsignedInt(cls, txt: str) -> int:
        """
        Parses an unsigned integer

        Parameters
        ----------
        txt: :class:`str`
            The text of the value

        Returns
        -------
        :class:`int`
            The value, or 0 if the text has no valid prefix (eg. a negative number) or the value does not fit a 64-bit unsigned integer
        """

        match = _UnsignedIntPrefix.match(txt.strip(DumpValueWhitespace))
        if (match is None):
            return 0

        value = int(match.group())
        return value if (value <= _UnsignedLongLongMax) else 0

    @classmethod
    def parseDouble(cls, txt: str) -> float:
        """
        Parses a floating point number

        Parameters
        ----------
        txt: :class:`str`
            The text of the value

        Returns
        -------
        :class:`float`
            The value, or 0 if the text has no valid prefix or the value is too large for a double
        """

        match = _DoublePrefix.match(txt.strip(DumpValueWhitespace))
        if (match is None):
            return 0.0

        text = match.group()
        try:
            value = float(text)
        except ValueError:
            # "nan(...)": Python's float() takes no payload
            value = float(text.split("(", 1)[0])

        # too large for a double: from_chars reports it out of range and leaves the value at 0
        if (value in (float("inf"), float("-inf")) and "n" not in text.lower()):
            return 0.0
        return value


class DumpDataType():
    """
    Class for the type of one channel of a buffer element (eg. one of the three 32-bit floats of a
    ``R32G32B32_FLOAT`` position): how its text value in a 3DMigoto dump is read, and how it is stored
    as bytes (little-endian)

    Parameters
    ----------
    kind: :class:`DumpDataKinds`
        The kind of value the channel holds

    size: :class:`int`
        The number of bytes the channel takes

    Attributes
    ----------
    kind: :class:`DumpDataKinds`
        The kind of value the channel holds

    size: :class:`int`
        The number of bytes the channel takes
    """

    def __init__(self, kind: DumpDataKinds, size: int):
        self.kind = kind
        self.size = size

    def __eq__(self, other) -> bool:
        if (not isinstance(other, DumpDataType)):
            return NotImplemented
        return (self.kind, self.size) == (other.kind, other.size)

    def __repr__(self) -> str:
        return f"DumpDataType({self.kind}, {self.size})"

    def parse(self, txt: str) -> Union[int, float]:
        """
        Reads the text of one value in a dump

        Parameters
        ----------
        txt: :class:`str`
            The text of the value

        Returns
        -------
        Union[:class:`int`, :class:`float`]
            The value. See :class:`DumpValueTools` for how text that is not a valid number is read
        """

        if (self.kind == DumpDataKinds.SignedInt):
            return DumpValueTools.parseSignedInt(txt)
        if (self.kind == DumpDataKinds.UnsignedInt):
            return DumpValueTools.parseUnsignedInt(txt)
        return DumpValueTools.parseDouble(txt)

    def getZero(self) -> Union[int, float]:
        """
        Retrieves the value a missing value is read as

        Returns
        -------
        Union[:class:`int`, :class:`float`]
            0, as the kind of number the channel holds
        """

        return 0 if (self.kind in (DumpDataKinds.SignedInt, DumpDataKinds.UnsignedInt)) else 0.0

    def _encodeInts(self, values: List[int]) -> np.ndarray:
        # the value's lowest 'size' bytes, in two's complement for a negative value
        mask = (1 << (8 * self.size)) - 1
        raw = np.array([value & mask for value in values], dtype = "<u8")
        return raw.view(np.uint8).reshape(-1, 8)[:, :self.size]

    def encode(self, values: List[Union[int, float]]) -> np.ndarray:
        """
        Stores values as bytes

        .. note::
            - A 32-bit float is rounded to the nearest float
            - A 16-bit float is TRUNCATED (not rounded), a value too small for a normal 16-bit float becomes 0, and a value too large (or not a number) becomes infinity
            - An integer keeps its lowest bytes
            - A ``UNORM`` value is multiplied by the channel's largest integer and truncated towards 0

        Parameters
        ----------
        values: List[Union[:class:`int`, :class:`float`]]
            The values, one per line of the buffer

        Returns
        -------
        numpy.ndarray
            The bytes, one row of :attr:`size` bytes per value
        """

        if (self.kind == DumpDataKinds.Float):
            with np.errstate(over = "ignore", invalid = "ignore"):
                floats = np.array(values, dtype = np.float64).astype("<f4")

            if (self.size == 4):
                return floats.view(np.uint8).reshape(-1, 4)

            bits = floats.view("<u4").astype(np.int64)
            sign = (bits >> 16) & 0x8000
            exponent = ((bits >> 23) & 0xFF) - 127 + 15
            mantissa = bits & 0x7FFFFF
            half = np.where(exponent <= 0, sign, np.where(exponent >= 0x1F, sign | 0x7C00, sign | (exponent << 10) | (mantissa >> 13)))
            return half.astype("<u2").view(np.uint8).reshape(-1, 2)

        if (self.kind == DumpDataKinds.Unorm):
            maxValue = float((1 << (8 * self.size)) - 1)
            ints = []
            for value in values:
                scaled = value * maxValue
                ints.append(0 if (math.isnan(scaled) or math.isinf(scaled)) else math.trunc(scaled))
            return self._encodeInts(ints)

        return self._encodeInts(values)


#: The prefix of the full name of a DXGI format
DXGIFormatPrefix = "DXGI_FORMAT_"

# The DXGI formats a buffer element may be declared with, and how each one is decoded: the numpy dtype
#   of one channel and the number of channels.
#
# note: this is a dict and not an Enum on purpose -- several formats decode the same way
#   (R8G8B8A8_UINT and R8G8B8A8_UNORM), and an Enum would make those aliases of one member

#: The DXGI formats a buffer element can be decoded from (without the ``DXGI_FORMAT_`` prefix), each with the numpy dtype of one channel and the number of channels
DXGIFormats: Dict[str, Tuple[str, int]] = {
    "R32G32B32A32_FLOAT": ("<f4", 4), "R32G32B32_FLOAT": ("<f4", 3), "R32G32_FLOAT": ("<f4", 2), "R32_FLOAT": ("<f4", 1),
    "R16G16B16A16_FLOAT": ("<f2", 4), "R16G16B16_FLOAT": ("<f2", 3), "R16G16_FLOAT": ("<f2", 2), "R16_FLOAT": ("<f2", 1),
    "R8G8B8A8_UINT": ("u1", 4), "R8G8B8A8_UNORM": ("u1", 4), "R8G8B8A8_SNORM": ("i1", 4), "R8G8B8_SNORM": ("i1", 3), "R8_SNORM": ("i1", 1), "R8_UINT": ("u1", 1), "R8_UNORM": ("u1", 1),
    "R16G16B16A16_UINT": ("<u2", 4), "R16G16B16A16_UNORM": ("<u2", 4), "R16G16_UNORM": ("<u2", 2), "R16_UINT": ("<u2", 1),
    "R32G32B32A32_UINT": ("<u4", 4), "R32_UINT": ("<u4", 1),
}


# the channels of a format: a letter and its bit width each, eg. "R32G32B32" is three 32-bit channels
_ChannelPattern = re.compile(r"[A-Za-z]([0-9]+)")


class DumpElement():
    """
    Class for one element of a vertex buffer in a 3DMigoto dump (eg. the ``POSITION`` of every vertex)

    Parameters
    ----------
    name: :class:`str`
        The semantic name of the element (eg. ``POSITION``)

    formatName: :class:`str`
        The DXGI format of the element (eg. ``R32G32B32_FLOAT``)

    dataTypes: List[:class:`DumpDataType`]
        The type of each channel of the element, in order

    Attributes
    ----------
    name: :class:`str`
        The semantic name of the element (eg. ``POSITION``)

    formatName: :class:`str`
        The DXGI format of the element (eg. ``R32G32B32_FLOAT``)

    dataTypes: List[:class:`DumpDataType`]
        The type of each channel of the element, in order
    """

    def __init__(self, name: str, formatName: str, dataTypes: List[DumpDataType]):
        self.name = name
        self.formatName = formatName
        self.dataTypes = dataTypes

    @property
    def size(self) -> int:
        """
        The number of bytes the element takes in one vertex

        :getter: Retrieves the size
        :type: :class:`int`
        """

        return sum(dataType.size for dataType in self.dataTypes)

    @classmethod
    def parseFormat(cls, formatName: str) -> Optional[List[DumpDataType]]:
        """
        Retrieves the channel types of a DXGI format

        Parameters
        ----------
        formatName: :class:`str`
            The DXGI format, with or without the ``DXGI_FORMAT_`` prefix (eg. ``R32G32B32_FLOAT``)

        Returns
        -------
        Optional[List[:class:`DumpDataType`]]
            The type of each channel, or ``None`` if any channel of the format cannot be read (eg. a ``SNORM``, or a channel narrower than a byte)
        """

        if (formatName.upper().startswith(DXGIFormatPrefix)):
            formatName = formatName[len(DXGIFormatPrefix):]

        channels, separator, suffix = formatName.partition("_")
        if (not separator):
            return None

        try:
            kind = DumpDataKinds(suffix)
        except ValueError:
            return None

        result = []
        for bits in _ChannelPattern.findall(channels):
            size = int(bits) // 8
            if (size == 0 or size > 8 or (kind == DumpDataKinds.Float and size not in (2, 4))):
                return None
            result.append(DumpDataType(kind, size))

        return result if (result) else None


VertexDataMarker = "vertex-data:"


class VbDumpFile():
    """
    Class for a vertex buffer dumped by 3DMigoto as text (a ``*-vb0=<hash>.txt`` file): a header naming
    the buffer's elements, then each vertex's values

    .. code-block::

        stride: 92
        vertex count: 16062
        topology: trianglelist
        element[0]:
          SemanticName: POSITION
          SemanticIndex: 0
          Format: R32G32B32_FLOAT
          ...

        vertex-data:

        vb0[0]+000 POSITION: 0.0136, 1.4219, -0.0476
        vb0[0]+012 NORMAL: 0.4588, 0.2117, -0.8627
        ...

        vb0[1]+000 POSITION: 0.0145, 1.4171, -0.0464
        ...

    .. note::
        The text is read the way AG Remap's ``VbFile.readDumpStr`` reads it, so the bytes are the same:

        - every non-blank line gives the comma-separated values after its last ``:``
        - a blank line ends a vertex, whose values fill the elements' channels in order: missing values are 0 and extra values are ignored
        - a value is read as :class:`DumpValueTools` describes

    Parameters
    ----------
    elements: List[:class:`DumpElement`]
        The elements of one vertex, in order

    data: :class:`bytes`
        The buffer, one vertex after another

    Attributes
    ----------
    elements: List[:class:`DumpElement`]
        The elements of one vertex, in order

    data: :class:`bytes`
        The buffer, one vertex after another
    """

    def __init__(self, elements: List[DumpElement], data: bytes):
        self.elements = elements
        self.data = data

    @property
    def bytesPerLine(self) -> int:
        """
        The number of bytes of one vertex

        :getter: Retrieves the stride
        :type: :class:`int`
        """

        return sum(element.size for element in self.elements)

    @property
    def vertexCount(self) -> int:
        """
        The number of vertices in the buffer

        :getter: Retrieves the vertex count
        :type: :class:`int`
        """

        bytesPerLine = self.bytesPerLine
        return 0 if (bytesPerLine == 0) else len(self.data) // bytesPerLine

    @classmethod
    def _findHeaderValues(cls, header: str, label: str) -> List[str]:
        # every value of a labelled line, in order: the first word after each 'label'
        return [match.group(1) for match in re.finditer(re.escape(label) + r"[ \t]*(\S*)", header)]

    @classmethod
    def parseHeader(cls, txt: str) -> Optional[List[DumpElement]]:
        """
        Reads the elements a dump's header declares

        Parameters
        ----------
        txt: :class:`str`
            The text of the dump

        Returns
        -------
        Optional[List[:class:`DumpElement`]]
            The elements, or ``None`` if the dump has no ``vertex-data:`` marker, its ``SemanticName`` and ``Format`` lines do not pair up, or any element's format cannot be read
        """

        headerEnd = txt.find(VertexDataMarker)
        if (headerEnd == -1):
            return None

        header = txt[:headerEnd]
        names = cls._findHeaderValues(header, "SemanticName:")
        formatNames = cls._findHeaderValues(header, "Format:")
        if (not names or len(names) != len(formatNames)):
            return None

        result = []
        for name, formatName in zip(names, formatNames):
            dataTypes = DumpElement.parseFormat(formatName)
            if (dataTypes is None):
                return None
            result.append(DumpElement(name, formatName, dataTypes))

        return result

    @classmethod
    def fromTxt(cls, txt: str):
        """
        Reads a dump's text

        Parameters
        ----------
        txt: :class:`str`
            The text of the dump

        Returns
        -------
        Optional[:class:`VbDumpFile`]
            The buffer, or ``None`` if the header's elements cannot be read (see :meth:`parseHeader`)
        """

        elements = cls.parseHeader(txt)
        if (elements is None):
            return None

        dataTypes = [dataType for element in elements for dataType in element.dataTypes]
        columns = [[] for _ in dataTypes]

        start = txt.find(VertexDataMarker)
        lineEnd = txt.find("\n", start)
        lines = [] if (lineEnd == -1) else txt[lineEnd + 1:].split("\n")

        block = []

        def addBlock():
            if (not block):
                return

            for i, dataType in enumerate(dataTypes):
                columns[i].append(dataType.parse(block[i]) if (i < len(block)) else dataType.getZero())
            block.clear()

        for line in lines:
            if (not line.strip(DumpValueWhitespace)):
                addBlock()
                continue

            # the values are whatever follows the last ':', which skips the "vb0[i]+offset NAME:" part
            block.extend(line.rpartition(":")[2].split(","))

        addBlock()

        if (not columns or not columns[0]):
            return cls(elements, b"")

        rows = np.concatenate([dataType.encode(column) for dataType, column in zip(dataTypes, columns)], axis = 1)
        return cls(elements, np.ascontiguousarray(rows).tobytes())

    @classmethod
    def read(cls, path: str):
        """
        Reads a dump

        Parameters
        ----------
        path: :class:`str`
            The path to the dump

        Returns
        -------
        Optional[:class:`VbDumpFile`]
            The buffer, or ``None`` if the header's elements cannot be read (see :meth:`parseHeader`)
        """

        with open(path, "r", encoding = FileEncodings.UTF8.value) as f:
            return cls.fromTxt(f.read())


class IbDumpFile():
    """
    Class for an index buffer dumped by 3DMigoto as text (a ``*-ib=<hash>.txt`` file): a header, then
    one triangle's three indices per line

    .. code-block::

        byte offset: 0
        first index: 20913
        index count: 30846
        topology: trianglelist
        format: DXGI_FORMAT_R16_UINT

        5988 5989 5990
        5988 5990 5991
        ...

    .. note::
        The text is read the way AG Remap's ``IbFile.readDumpStr`` reads it, so the indices are the same:

        - a line holding a ``:`` is a header line, and a blank line is skipped
        - every other line is one triangle: its space-separated values fill three indices, missing values are 0 and extra values are ignored
        - a value is read as an unsigned integer, as :class:`DumpValueTools` describes, and kept to 32 bits

    Parameters
    ----------
    indices: numpy.ndarray
        The indices, as ``uint32``

    Attributes
    ----------
    indices: numpy.ndarray
        The indices, as ``uint32``
    """

    def __init__(self, indices: np.ndarray):
        self.indices = indices

    @property
    def indexCount(self) -> int:
        """
        The number of indices

        :getter: Retrieves the index count
        :type: :class:`int`
        """

        return int(self.indices.size)

    @classmethod
    def fromTxt(cls, txt: str):
        """
        Reads a dump's text

        Parameters
        ----------
        txt: :class:`str`
            The text of the dump

        Returns
        -------
        :class:`IbDumpFile`
            The index buffer
        """

        indices = []
        for line in txt.split("\n"):
            trimmed = line.lstrip(DumpValueWhitespace)
            if (not trimmed or ":" in trimmed):
                continue

            values = [value for value in trimmed.split(" ") if value]
            for i in range(3):
                indices.append((DumpValueTools.parseUnsignedInt(values[i]) if (i < len(values)) else 0) & 0xFFFFFFFF)

        return cls(np.array(indices, dtype = "<u4"))

    @classmethod
    def read(cls, path: str):
        """
        Reads a dump

        Parameters
        ----------
        path: :class:`str`
            The path to the dump

        Returns
        -------
        :class:`IbDumpFile`
            The index buffer
        """

        with open(path, "r", encoding = FileEncodings.UTF8.value) as f:
            return cls.fromTxt(f.read())


class GIMIIdentityMod():
    """
    Class for a generated GIMI identity mod: what was written, and what was left out

    Parameters
    ----------
    name: :class:`str`
        The name of the character in the mod's files and sections

    folder: :class:`str`
        The folder the mod was written into

    components: List[:class:`GIMIComponent`]
        The skinned components of the character, in the order of ``hash.json``

    faceDiffuse: Optional[:class:`str`]
        The file name in the mod of the face's diffuse texture, or ``None`` if the mod has none

    faceRegister: :class:`str`
        The register the face's diffuse texture is bound to

    unskinned: List[:class:`str`]
        The names of the components left out because they are not skinned

    Attributes
    ----------
    name: :class:`str`
        The name of the character in the mod's files and sections

    folder: :class:`str`
        The folder the mod was written into

    components: List[:class:`GIMIComponent`]
        The skinned components of the character, in the order of ``hash.json``

    faceDiffuse: Optional[:class:`str`]
        The file name in the mod of the face's diffuse texture, or ``None`` if the mod has none

    faceRegister: :class:`str`
        The register the face's diffuse texture is bound to

    unskinned: List[:class:`str`]
        The names of the components left out because they are not skinned
    """

    def __init__(self, name: str, folder: str, components: List[GIMIComponent], faceDiffuse: Optional[str], faceRegister: str, unskinned: List[str]):
        self.name = name
        self.folder = folder
        self.components = components
        self.faceDiffuse = faceDiffuse
        self.faceRegister = faceRegister
        self.unskinned = unskinned

    @property
    def unbound(self) -> List[str]:
        """
        The objects (``<component><object>``) drawn with the game's own textures, because they have no textures to bind

        :getter: Retrieves the objects
        :type: List[:class:`str`]
        """

        return [f"{component.name}{obj}" for component in self.components for obj in component.objects if not component.boundTextures[obj][2]]

    def getSummary(self) -> List[str]:
        """
        Describes the mod: its components, objects, textures and what was left out

        Returns
        -------
        List[:class:`str`]
            The lines of the description
        """

        lines = []
        for component in self.components:
            triangles = ", ".join(f"{obj} {component.indices[obj].size // 3} triangles from index {first}" for obj, first in zip(component.objects, component.firstIndices))
            lines.append(f"{self.name}{component.name}: {component.vertexCount} vertices (texcoord stride {component.strides[GIMIBuffers.Texcoord]}); {triangles}")

            drawn = []
            for obj in component.objects:
                sourceComponent, sourceObj, bound = component.boundTextures[obj]
                if (bound):
                    borrowed = "" if ((sourceComponent, sourceObj) == (component.name, obj)) else f" <- {sourceComponent}{sourceObj}"
                    drawn.append(f"{obj} {'/'.join(bound)}{borrowed}")
            lines.append("  textures: " + (", ".join(drawn) or "none"))

        if (self.faceDiffuse):
            lines.append(f"  face: {self.faceDiffuse} on {self.faceRegister}")
        if (self.unskinned):
            lines.append(f"  skipped, unskinned (no blend_vb): {', '.join(self.unskinned)}")

        unbound = self.unbound
        if (unbound):
            lines.append(f"  NO textures bound (geometry only, no fix call): {', '.join(unbound)} -- point them at another component's textures")

        lines.append(f"  written to {self.folder}")
        return lines


class GIMITextureSource():
    """
    Class for where a component with no textures of its own reads its textures from: one object of
    another component (eg. YelanTranquil's Bang and Eye read her Body's slot A)

    Parameters
    ----------
    component: :class:`str`
        The name of the component that lends its textures

    obj: :class:`str`
        The name of the object of ``component`` whose textures are read

    layout: Optional[:class:`GIMITextureLayouts`]
        The layout the BORROWING component binds the textures in, which depends on the borrower's shader. If this value is ``None``, the textures are bound as they are: the normal map layout if the lender has a normal map :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Attributes
    ----------
    component: :class:`str`
        The name of the component that lends its textures

    obj: :class:`str`
        The name of the object of :attr:`component` whose textures are read

    layout: Optional[:class:`GIMITextureLayouts`]
        The layout the borrowing component binds the textures in
    """

    def __init__(self, component: str, obj: str, layout: Optional[GIMITextureLayouts] = None):
        self.component = component
        self.obj = obj
        self.layout = layout

    def __eq__(self, other) -> bool:
        if (not isinstance(other, GIMITextureSource)):
            return NotImplemented
        return (self.component, self.obj, self.layout) == (other.component, other.obj, other.layout)

    def __repr__(self) -> str:
        return f"GIMITextureSource({self.component!r}, {self.obj!r}, {self.layout})"

    def toDict(self) -> Dict[str, Any]:
        """
        Writes the source as a ``hash.json`` entry's ``texture_sources`` records it

        Returns
        -------
        Dict[:class:`str`, Any]
            ``{"component": ..., "object": ..., "layout": "normalMap" | "plain" | None}``
        """

        layout = {GIMITextureLayouts.NormalMap: "normalMap", GIMITextureLayouts.Plain: "plain"}.get(self.layout)
        return {"component": self.component, "object": self.obj, "layout": layout}

    @classmethod
    def fromDict(cls, data: Dict[str, Any]):
        """
        Reads a source as a ``hash.json`` entry's ``texture_sources`` records it (see :meth:`toDict`)

        Parameters
        ----------
        data: Dict[:class:`str`, Any]
            The record

        Raises
        ------
        :class:`BadAssetData`
            If the record is not a texture source

        Returns
        -------
        :class:`GIMITextureSource`
            The source
        """

        layouts = {None: None, "normalMap": GIMITextureLayouts.NormalMap, "plain": GIMITextureLayouts.Plain}
        if (not isinstance(data, dict) or "component" not in data or "object" not in data or data.get("layout") not in layouts):
            raise BadAssetData(f"{data!r} is not a texture source: {{\"component\": ..., \"object\": ..., \"layout\": \"normalMap\" | \"plain\" | null}}")
        return cls(data["component"], data["object"], layouts[data.get("layout")])

    @classmethod
    def parse(cls, txt: str) -> Tuple[str, "GIMITextureSource"]:
        """
        Reads a texture source written as ``<borrower>=<component>:<object>[:normalMap|plain]`` (eg. ``Bang=Body:A`` or ``Eye=Body:A:plain``)

        Parameters
        ----------
        txt: :class:`str`
            The text

        Raises
        ------
        :class:`Error`
            If the text is not in that form

        Returns
        -------
        Tuple[:class:`str`, :class:`GIMITextureSource`]
            The name of the borrowing component, and where it reads its textures from
        """

        usage = f"a texture source is <component>=<component>:<object>[:normalMap|plain], not {txt!r}"
        borrower, separator, source = txt.partition("=")
        if (not separator or ":" not in source):
            raise Error(usage)

        fields = source.split(":")
        if (len(fields) not in (2, 3)):
            raise Error(usage)

        layout = None
        if (len(fields) == 3):
            layouts = {"normalMap": GIMITextureLayouts.NormalMap, "plain": GIMITextureLayouts.Plain}
            if (fields[2] not in layouts):
                raise Error(f"a texture source's layout is normalMap or plain, not {fields[2]!r}")
            layout = layouts[fields[2]]

        return borrower, cls(fields[0], fields[1], layout)


class GIMIIdentityModGenerator(Model):
    """
    Generates the identity mod of a GI character: the game's own model, written out as a
    GIMI mod from the character's asset folder

    The asset folder is laid out as `GI-Model-Importer-Assets <https://github.com/SilentNightSound/GI-Model-Importer-Assets>`_'s
    ``PlayerCharacterData/<Name>`` folders are:

    - ``hash.json``, with the hashes, objects and textures of each component
    - ``<prefix><component><object>-vb0=<hash>.txt`` and ``<prefix><component><object>-ib=<hash>.txt``: the 3DMigoto dumps of each object's vertex and index buffers
    - ``<prefix><component><object><kind>.dds``: the textures

    For each skinned component (a ``hash.json`` entry with a ``position_vb`` and a ``blend_vb``) the mod gets:

    - ``<name><component>Position.buf``, ``<name><component>Blend.buf`` and ``<name><component>Texcoord.buf``: the dumped vertex buffer, split as GIMI lays it out
    - ``<name><component><object>.ib``: each object's indices, as ``R32_UINT``
    - ``<name><component><object><kind>.dds``: each object's textures

    and the mod also gets ``<name>FaceHeadDiffuse.dds`` (the face's diffuse) and ``<name>.ini``. ``<component>``
    is the empty string for an older character, which is a single component.

    Examples
    --------
    .. code-block:: python
        :linenos:

        import AGIDMGen as IDMG

        generator = IDMG.GIMIIdentityModGenerator()
        mod = generator.generate("GI-Model-Importer-Assets/PlayerCharacterData/Yelan", "Mods/YelanIdentity")
        print("\\n".join(mod.getSummary()))

        # a component with no textures of its own reads another's
        generator = IDMG.GIMIIdentityModGenerator(faceRegister = "ps-t1", textureSources = {
            "Bang": IDMG.GIMITextureSource("Body", "A"),
            "Eye": IDMG.GIMITextureSource("Body", "A", IDMG.GIMITextureLayouts.Plain)})
        generator.generate("GI-Model-Importer-Assets/PlayerCharacterData/YelanTranquil", "Mods/YelanTranquilIdentity")

    Parameters
    ----------
    includeFix: :class:`bool`
        Whether an object that binds textures runs the ``ORFix`` command list of its layout :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``True``

    faceRegister: :class:`str`
        The register the face's diffuse texture is bound to. Some skins of version 6.0 or newer bind it to ``ps-t1`` :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``"ps-t0"``

    textureSources: Optional[Dict[:class:`str`, :class:`GIMITextureSource`]]
        For each component with no textures of its own, where it reads its textures from. If this value is ``None``, no component borrows textures :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    logger: Optional[:class:`BaseLogger`]
        Where to report what is done. If this value is ``None``, nothing is reported :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Attributes
    ----------
    includeFix: :class:`bool`
        Whether an object that binds textures runs the ``ORFix`` command list of its layout

    faceRegister: :class:`str`
        The register the face's diffuse texture is bound to

    textureSources: Dict[:class:`str`, :class:`GIMITextureSource`]
        For each component with no textures of its own, where it reads its textures from
    """

    def __init__(self, includeFix: bool = True, faceRegister: str = "ps-t0", textureSources: Optional[Dict[str, GIMITextureSource]] = None,
                 logger: Optional[BaseLogger] = None):
        super().__init__(logger = logger)
        self.includeFix = includeFix
        self.faceRegister = faceRegister
        self.textureSources = {} if (textureSources is None) else textureSources

    @classmethod
    def readHashes(cls, assetsFolder: str) -> List[Dict[str, Any]]:
        """
        Reads the ``hash.json`` of an asset folder

        Parameters
        ----------
        assetsFolder: :class:`str`
            The asset folder

        Raises
        ------
        :class:`BadAssetData`
            If the asset folder has no ``hash.json``

        Returns
        -------
        List[Dict[:class:`str`, Any]]
            The entries of ``hash.json``
        """

        path = os.path.join(assetsFolder, "hash.json")
        if (not os.path.isfile(path)):
            raise BadAssetData(f"'{path}' is missing")

        with open(path, "r", encoding = FileEncodings.UTF8.value) as f:
            return json.load(f)

    @classmethod
    def buildBuffers(cls, vbDump: VbDumpFile, dumpName: str) -> Tuple[Dict[GIMIBuffers, bytes], Dict[GIMIBuffers, int]]:
        """
        Splits a dumped vertex buffer into GIMI's vertex buffers

        Parameters
        ----------
        vbDump: :class:`VbDumpFile`
            The dumped vertex buffer

        dumpName: :class:`str`
            The file name of the dump, for the error messages

        Raises
        ------
        :class:`BadAssetData`
            If an element belongs to no GIMI buffer, a buffer's elements are not side by side, a buffer is missing, or the Position or Blend buffer is not the size GIMI fixes

        Returns
        -------
        Tuple[Dict[:class:`GIMIBuffers`, :class:`bytes`], Dict[:class:`GIMIBuffers`, :class:`int`]]
            The contents of each buffer, and the number of bytes of one vertex in each
        """

        ranges: Dict[GIMIBuffers, List[int]] = {}
        offset = 0
        for element in vbDump.elements:
            buffer = GIMISemanticBuffers.get(element.name.rstrip("0123456789"))
            if (buffer is None):
                raise BadAssetData(f"{dumpName}: element {element.name} belongs to no .buf file")

            span = ranges.setdefault(buffer, [offset, offset])
            if (span[1] != offset):
                raise BadAssetData(f"{dumpName}: {buffer.value} elements are not contiguous ({element.name} at {offset})")

            span[1] = offset + element.size
            offset += element.size

        for buffer in GIMIBuffers:
            if (buffer not in ranges):
                raise BadAssetData(f"{dumpName}: no element belongs to the {buffer.value} buffer")

        rows = np.frombuffer(vbDump.data, dtype = np.uint8).reshape(vbDump.vertexCount, vbDump.bytesPerLine)
        buffers = {}
        strides = {}
        for buffer in GIMIBuffers:
            start, end = ranges[buffer]
            if (buffer in GIMIFixedStrides and (end - start) != GIMIFixedStrides[buffer]):
                raise BadAssetData(f"{dumpName}: {buffer.value} spans {end - start} bytes, GIMI's stride is {GIMIFixedStrides[buffer]}")

            buffers[buffer] = rows[:, start:end].tobytes()
            strides[buffer] = end - start

        return buffers, strides

    def _getBoundTextures(self, components: Dict[str, GIMIComponent], comp: str, obj: str) -> Tuple[str, str, Dict[str, str]]:
        # the object's own textures; else the source given for its component; else the source its hash.json records for it
        own = components[comp].textures.get(obj, {})
        if (own):
            return comp, obj, own

        source = self.textureSources.get(comp)
        recorded = components[comp].entry.get("texture_sources", {}).get(obj)
        if (source is None and recorded is not None):
            source = GIMITextureSource.fromDict(recorded)
        if (source is None):
            return comp, obj, {}

        borrowed = dict(components[source.component].textures.get(source.obj, {}))
        if (source.layout == GIMITextureLayouts.Plain):
            borrowed.pop("NormalMap", None)
        return source.component, source.obj, borrowed

    def generate(self, assetsFolder: str, modFolder: str, name: Optional[str] = None, assetPrefix: Optional[str] = None) -> GIMIIdentityMod:
        """
        Generates the identity mod of a character

        Parameters
        ----------
        assetsFolder: :class:`str`
            The character's asset folder

        modFolder: :class:`str`
            The folder to write the mod into. It is created if it does not exist

        name: Optional[:class:`str`]
            The name of the character in the mod's files and sections. If this value is ``None``, ``assetPrefix`` is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        assetPrefix: Optional[:class:`str`]
            What the names of the asset folder's files start with (eg. ``Citlali_WhisperOfStars``). If this value is ``None``, the name of ``assetsFolder`` is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        Raises
        ------
        :class:`BadAssetData`
            If the asset folder is missing a file, or its data does not agree with itself

        :class:`Error`
            If a texture source names a component or object the character does not have

        Returns
        -------
        :class:`GIMIIdentityMod`
            The mod generated
        """

        assetsFolderName = os.path.basename(os.path.normpath(assetsFolder))
        prefix = assetsFolderName if (assetPrefix is None) else assetPrefix
        name = prefix if (name is None) else name

        self.print("log", f"Reading the asset folder {assetsFolder}")
        hashes = self.readHashes(assetsFolder)
        entries, unskinned, face = self._getEntries(hashes, name)

        # ---- read everything before writing anything ----
        components: Dict[str, GIMIComponent] = {}
        textureCopies: List[Tuple[str, str]] = []

        for entry in entries:
            comp = entry.get("component_name", "")
            objects = list(entry["object_classifications"])

            # every object's vb0 dump is the component's whole vertex buffer; the first one serves
            dumpName = f"{prefix}{comp}{objects[0]}-vb0={entry['position_vb']}.txt"
            vbPath = os.path.join(assetsFolder, dumpName)
            if (not os.path.isfile(vbPath)):
                raise BadAssetData(f"'{vbPath}' is missing")

            vbDump = VbDumpFile.read(vbPath)
            if (vbDump is None):
                raise BadAssetData(f"{dumpName}: its header's elements cannot be read")

            buffers, strides = self.buildBuffers(vbDump, dumpName)
            vertexCount = vbDump.vertexCount

            indices = {}
            for obj in objects:
                ibPath = os.path.join(assetsFolder, f"{prefix}{comp}{obj}-ib={entry['ib']}.txt")
                if (not os.path.isfile(ibPath)):
                    raise BadAssetData(f"'{ibPath}' is missing")
                indices[obj] = IbDumpFile.read(ibPath).indices

            textures = self._getTextures(assetsFolder, prefix, name, entry, textureCopies)
            components[comp] = self._makeComponent(comp, entry, vertexCount, buffers, strides, indices, textures)

        faceDiffuse, faceHash = self._getFace(face, lambda obj: os.path.join(assetsFolder, f"{prefix}Face{obj}Diffuse.dds"), name, textureCopies)
        return self._write(name, modFolder, components, textureCopies, faceDiffuse, faceHash, unskinned, f"its asset folder ({assetsFolderName})")

    def generateFromRepo(self, name: str, modFolder: str, version: Optional[str] = None, downloader: Optional[ModDownloader] = None,
                         downloadFolder: Optional[str] = None, modName: Optional[str] = None) -> GIMIIdentityMod:
        """
        Generates the identity mod of a character from its download folder, downloaded from the repositories
        of :class:`ModDownloadRepos`, so no asset folder is needed

        Parameters
        ----------
        name: :class:`str`
            The character's name (see :meth:`ModDownloader.getName`)

        modFolder: :class:`str`
            The folder to write the mod into. It is created if it does not exist

        version: Optional[:class:`str`]
            The game version wanted (eg. ``4.0``). If this value is ``None``, the newest download folder is used (see :meth:`ModDownloader.find`) :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        downloader: Optional[:class:`ModDownloader`]
            What downloads the files (eg. one given local copies of the repositories). If this value is ``None``, every file is downloaded :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        downloadFolder: Optional[:class:`str`]
            The folder to keep the downloaded files in. If this value is ``None``, they are downloaded into a temporary folder that is deleted afterwards :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        modName: Optional[:class:`str`]
            The name of the character in the mod. If this value is ``None``, the prefix of the download folder's files is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        Raises
        ------
        :class:`Error`
            If no character has that name, or ``version`` is not a game version

        :class:`DownloadFailed`
            If a file cannot be downloaded

        :class:`BadAssetData`
            If the downloaded files do not agree with each other

        Returns
        -------
        :class:`GIMIIdentityMod`
            The mod generated
        """

        downloader = ModDownloader(logger = self.logger) if (downloader is None) else downloader
        download = downloader.find(ModLoaders.GIMI, name, version)

        with tempfile.TemporaryDirectory() as temp:
            downloader.download(download, temp if (downloadFolder is None) else downloadFolder)
            # named by what it is, not by where it was downloaded to (a temporary folder's name is random)
            sourceName = f"{ModDownloadGameFolders[download.loader]}/{download.name}/{download.version}"
            return self.generateFromDownload(download.folder, modFolder, download.prefix, name = modName, sourceName = sourceName)

    def generateFromDownload(self, downloadFolder: str, modFolder: str, prefix: str, name: Optional[str] = None,
                             sourceName: Optional[str] = None) -> GIMIIdentityMod:
        """
        Generates the identity mod of a character from its download folder, laid out as Anime Game Remap's
        ``Data/Mod Downloads/GI/<Name>/<version>`` folders are:

        - ``<prefix>Hash.json``: the asset folder's ``hash.json``
        - ``<prefix><component>Position.buf``, ``Blend.buf`` and ``Texcoord.buf``: the GIMI vertex buffers of each skinned component
        - ``<prefix><component><object>.ib``: each object's indices, as ``R32_UINT``
        - ``<prefix><component><object><kind>.dds`` and ``<prefix>FaceDiffuse.dds``: the textures

        :class:`GIMIDownloadFolderBuilder` writes such a folder from an asset folder.

        Parameters
        ----------
        downloadFolder: :class:`str`
            The download folder

        modFolder: :class:`str`
            The folder to write the mod into. It is created if it does not exist

        prefix: :class:`str`
            What the names of the download folder's files start with

        name: Optional[:class:`str`]
            The name of the character in the mod's files and sections. If this value is ``None``, ``prefix`` is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        sourceName: Optional[:class:`str`]
            What the ``.ini``'s last comment calls the download folder (eg. ``GI/Yelan/4_0``). If this value is ``None``, the name of ``downloadFolder`` is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        Raises
        ------
        :class:`BadAssetData`
            If the download folder is missing a file, or its data does not agree with itself

        :class:`Error`
            If a texture source names a component or object the character does not have

        Returns
        -------
        :class:`GIMIIdentityMod`
            The mod generated
        """

        name = prefix if (name is None) else name
        self.print("log", f"Reading the download folder {downloadFolder}")
        hashPath = os.path.join(downloadFolder, f"{prefix}{GIMIHashFileSuffix}")
        if (not os.path.isfile(hashPath)):
            raise BadAssetData(f"'{hashPath}' is missing")

        with open(hashPath, "r", encoding = FileEncodings.UTF8.value) as f:
            hashes = json.load(f)
        entries, unskinned, face = self._getEntries(hashes, name)

        components: Dict[str, GIMIComponent] = {}
        textureCopies: List[Tuple[str, str]] = []

        for entry in entries:
            comp = entry.get("component_name", "")
            buffers = {}
            for buffer in GIMIBuffers:
                path = os.path.join(downloadFolder, f"{prefix}{comp}{buffer.value}.buf")
                if (not os.path.isfile(path)):
                    raise BadAssetData(f"'{path}' is missing")
                with open(path, "rb") as f:
                    buffers[buffer] = f.read()

            vertexCount = len(buffers[GIMIBuffers.Position]) // GIMIFixedStrides[GIMIBuffers.Position]
            strides = {buffer: (len(data) // vertexCount if (vertexCount) else GIMIFixedStrides.get(buffer, 0)) for buffer, data in buffers.items()}
            for buffer, data in buffers.items():
                if (len(data) != vertexCount * strides[buffer] or (buffer in GIMIFixedStrides and strides[buffer] != GIMIFixedStrides[buffer])):
                    raise BadAssetData(f"{prefix}{comp}{buffer.value}.buf is {len(data)} bytes, which is not {vertexCount} vertices of a GIMI {buffer.value} buffer")

            indices = {}
            for obj in entry["object_classifications"]:
                path = os.path.join(downloadFolder, f"{prefix}{comp}{obj}.ib")
                if (not os.path.isfile(path)):
                    raise BadAssetData(f"'{path}' is missing")
                indices[obj] = np.fromfile(path, dtype = "<u4")

            textures = self._getTextures(downloadFolder, prefix, name, entry, textureCopies)
            components[comp] = self._makeComponent(comp, entry, vertexCount, buffers, strides, indices, textures)

        faceDiffuse, faceHash = self._getFace(face, lambda obj: os.path.join(downloadFolder, f"{prefix}FaceDiffuse.dds"), name, textureCopies)
        return self._write(name, modFolder, components, textureCopies, faceDiffuse, faceHash, unskinned,
                           f"its download folder ({os.path.basename(os.path.normpath(downloadFolder)) if (sourceName is None) else sourceName})")

    def _getEntries(self, hashes: List[Dict[str, Any]], name: str) -> Tuple[List[Dict[str, Any]], List[str], Optional[Dict[str, Any]]]:
        # the skinned components, the names of the unskinned ones and the face entry, checked
        entries = [h for h in hashes if h.get("position_vb") and h.get("blend_vb")]
        unskinned = [h.get("component_name", "") for h in hashes if h.get("position_vb") and not h.get("blend_vb")]
        face = next((h for h in hashes if h.get("component_name") == "Face"), None)
        if (not entries):
            raise BadAssetData(f"{name}: hash.json has no entry with a position_vb and a blend_vb")

        for entry in entries:
            for key in ("texcoord_vb", "draw_vb", "ib", "object_classifications", "object_indexes"):
                if (key not in entry):
                    raise BadAssetData(f"{name}: the hash.json entry of component '{entry.get('component_name', '')}' has no '{key}'")
            if (not entry["object_classifications"]):
                raise BadAssetData(f"{name}: the hash.json entry of component '{entry.get('component_name', '')}' has no objects")

        names = [entry.get("component_name", "") for entry in entries]
        for entry in entries:
            for obj, record in entry.get("texture_sources", {}).items():
                source = GIMITextureSource.fromDict(record)
                lender = next((e for e in entries if e.get("component_name", "") == source.component), None)
                if (obj not in entry["object_classifications"] or lender is None or source.obj not in lender["object_classifications"]):
                    raise BadAssetData(f"{name}: hash.json records a texture source for {entry.get('component_name', '')}{obj} that the character does not have ({record!r})")

        for borrower, source in self.textureSources.items():
            if (borrower not in names):
                raise Error(f"the texture source names {borrower!r}, which is not one of this character's components ({', '.join(names)})")
            if (source.component not in names):
                raise Error(f"the texture source of {borrower!r} reads {source.component!r}, which is not one of this character's components ({', '.join(names)})")
            lender = entries[names.index(source.component)]
            if (source.obj not in lender["object_classifications"]):
                raise Error(f"the texture source of {borrower!r} reads the object {source.obj!r}, which component {source.component!r} does not have ({', '.join(lender['object_classifications'])})")

        return entries, unskinned, face

    @classmethod
    def _getTextures(cls, folder: str, prefix: str, name: str, entry: Dict[str, Any], textureCopies: List[Tuple[str, str]]) -> Dict[str, Dict[str, str]]:
        # the textures of each object that the folder has, as their file names in the mod
        comp = entry.get("component_name", "")
        textures = {}
        for obj, textureList in zip(entry["object_classifications"], entry.get("texture_hashes", [])):
            for kind, ext, _ in textureList:
                if (ext.lower() != ".dds"):
                    continue

                src = os.path.join(folder, f"{prefix}{comp}{obj}{kind}{ext}")
                if (os.path.exists(src)):
                    dst = f"{name}{comp}{obj}{kind}{ext}"
                    textureCopies.append((src, dst))
                    textures.setdefault(obj, {})[kind] = dst
        return textures

    @classmethod
    def _makeComponent(cls, comp: str, entry: Dict[str, Any], vertexCount: int, buffers: Dict[GIMIBuffers, bytes], strides: Dict[GIMIBuffers, int],
                       indices: Dict[str, np.ndarray], textures: Dict[str, Dict[str, str]]) -> GIMIComponent:
        for obj, ib in indices.items():
            if (ib.size and int(ib.max()) >= vertexCount):
                raise BadAssetData(f"{comp}{obj}: index {int(ib.max())} beyond the {vertexCount} vertices")
        return GIMIComponent(comp, entry, vertexCount, buffers, strides, indices, textures)

    @classmethod
    def _getFace(cls, face: Optional[Dict[str, Any]], getSource: Callable[[str], str], name: str, textureCopies: List[Tuple[str, str]]) -> Tuple[Optional[str], Optional[str]]:
        # the face's diffuse texture in the mod and its hash; 'getSource' gives the texture's path from the face's object
        if (face is None):
            return None, None

        faceObj = list(face["object_classifications"])[0]
        src = getSource(faceObj)
        if (not os.path.exists(src)):
            return None, None

        faceDiffuse = f"{name}Face{faceObj}Diffuse.dds"
        textureCopies.append((src, faceDiffuse))
        faceHash = next((h for kind, _, h in face["texture_hashes"][0] if kind == "Diffuse"), None)
        return faceDiffuse, faceHash

    def _write(self, name: str, modFolder: str, components: Dict[str, GIMIComponent], textureCopies: List[Tuple[str, str]],
               faceDiffuse: Optional[str], faceHash: Optional[str], unskinned: List[str], source: str) -> GIMIIdentityMod:
        for component in components.values():
            for obj in component.objects:
                component.boundTextures[obj] = self._getBoundTextures(components, component.name, obj)

        self.print("log", f"Writing the mod into {modFolder}")
        os.makedirs(modFolder, exist_ok = True)
        for component in components.values():
            for buffer, data in component.buffers.items():
                with open(os.path.join(modFolder, f"{name}{component.name}{buffer.value}.buf"), "wb") as f:
                    f.write(data)

            for obj, ib in component.indices.items():
                with open(os.path.join(modFolder, f"{name}{component.name}{obj}.ib"), "wb") as f:
                    f.write(ib.astype("<u4").tobytes())

        for src, dst in textureCopies:
            shutil.copy2(src, os.path.join(modFolder, dst))

        componentList = list(components.values())
        iniBuilder = GIMIIniBuilder(name, componentList, source, faceDiffuse = faceDiffuse, faceHash = faceHash,
                                    faceRegister = self.faceRegister, includeFix = self.includeFix)
        with open(os.path.join(modFolder, f"{name}.ini"), "w", encoding = FileEncodings.UTF8.value, newline = "\r\n") as f:
            f.write(iniBuilder.build())

        return GIMIIdentityMod(name, modFolder, componentList, faceDiffuse, self.faceRegister, unskinned)


class WWMIBuffers(Enum):
    """
    The buffer files of a WWMI mod, in the order the mod's ``Metadata.json`` export format lists them,
    and the file name each one is written to inside the mod's ``Meshes`` folder

    Attributes
    ----------
    Index: :class:`str`
        The index buffer of the whole mesh

    Position: :class:`str`
        The positions of the vertices

    Blend: :class:`str`
        The bone indices and bone weights of the vertices

    Vector: :class:`str`
        The tangents, normals and bitangent signs of the vertices

    Color: :class:`str`
        The vertex colours

    TexCoord: :class:`str`
        The texture coordinates of the vertices

    ShapeKeyOffset: :class:`str`
        Where each shape key's entries start in :attr:`ShapeKeyVertexId` and :attr:`ShapeKeyVertexOffset`

    ShapeKeyVertexId: :class:`str`
        The vertex of each shape key entry

    ShapeKeyVertexOffset: :class:`str`
        The position delta of each shape key entry

    BlendRemapVertexVG: :class:`str`
        Every vertex's full bone indices, for a mod that needs a blend remap

    BlendRemapForward: :class:`str`
        The local to merged bone index table of each blend remap

    BlendRemapReverse: :class:`str`
        The merged to local bone index table of each blend remap
    """

    Index = "Index.buf"
    Position = "Position.buf"
    Blend = "Blend.buf"
    Vector = "Vector.buf"
    Color = "Color.buf"
    TexCoord = "TexCoord.buf"
    ShapeKeyOffset = "ShapeKeyOffset.buf"
    ShapeKeyVertexId = "ShapeKeyVertexId.buf"
    ShapeKeyVertexOffset = "ShapeKeyVertexOffset.buf"
    BlendRemapVertexVG = "BlendRemapVertexVG.buf"
    BlendRemapForward = "BlendRemapForward.buf"
    BlendRemapReverse = "BlendRemapReverse.buf"


#: The buffers written only for a character whose merged skeleton needs WWMI's blend remap
WWMIBlendRemapBuffers = [WWMIBuffers.BlendRemapVertexVG, WWMIBuffers.BlendRemapForward, WWMIBuffers.BlendRemapReverse]

#: The number of shape key slots WWMI's shape key loader has
WWMIShapeKeySlots = 128

#: The most merged bones WWMI can skin, and so the length of each blend remap table
WWMIBlendRemapSize = 512

#: The number of bones the 8-bit bone indices of the Blend buffer can name, without a blend remap
WWMIBlendIndexLimit = 256

#: What each buffer's file name in a download folder ends with, before ``.buf`` (``<prefix><name>.buf``)
WWMIDownloadNames: Dict[WWMIBuffers, str] = {buffer: ("Texcoord" if (buffer == WWMIBuffers.TexCoord) else buffer.name) for buffer in WWMIBuffers}

#: What a texture's file name in a download folder ends with, after its prefix: ``Texture<hash>.dds``
WWMIDownloadTextureSuffix = re.compile(r"Texture(?P<hash>[0-9a-fA-F]{8})\.dds")


class WWMIDrawRange():
    """
    Class for where one component of a WuWa character lies in the character's mesh: its range of
    vertices and its range of the mesh's index buffer, as the ``components`` list of the character's
    ``Metadata.json`` records them

    Parameters
    ----------
    index: :class:`int`
        The number of the component

    entry: Dict[:class:`str`, Any]
        The component's entry in the ``components`` list of ``Metadata.json``

    Raises
    ------
    :class:`BadAssetData`
        If ``entry`` lacks one of ``vertex_offset``, ``vertex_count``, ``index_offset`` or ``index_count``

    Attributes
    ----------
    index: :class:`int`
        The number of the component

    entry: Dict[:class:`str`, Any]
        The component's entry in the ``components`` list of ``Metadata.json``

    vertexOffset: :class:`int`
        Where the component's vertices start in the whole mesh

    indexOffset: :class:`int`
        Where the component's indices start in the whole mesh's index buffer
    """

    def __init__(self, index: int, entry: Dict[str, Any]):
        self.index = index
        self.entry = entry

        for key in ("vertex_offset", "index_offset"):
            if (key not in entry):
                raise BadAssetData(f"Component {index} of Metadata.json has no '{key}'")

        self.vertexOffset = int(entry["vertex_offset"])
        self.indexOffset = int(entry["index_offset"])

    @property
    def vertexCount(self) -> int:
        """
        The number of vertices in the component

        :getter: Retrieves the vertex count
        :type: :class:`int`
        """

        if ("vertex_count" not in self.entry):
            raise BadAssetData(f"Component {self.index} of Metadata.json has no 'vertex_count'")
        return int(self.entry["vertex_count"])

    @property
    def indexCount(self) -> int:
        """
        The number of indices in the component

        :getter: Retrieves the index count
        :type: :class:`int`
        """

        if ("index_count" not in self.entry):
            raise BadAssetData(f"Component {self.index} of Metadata.json has no 'index_count'")
        return int(self.entry["index_count"])


class WWMIBlendRemap():
    """
    Class for one blend remap of a WWMI mod: the table that lets one component of a character, whose
    merged skeleton has more bones than the 8-bit indices of the Blend buffer can name, address the
    bones it uses

    Parameters
    ----------
    componentIndex: :class:`int`
        The number of the component that the remap is for

    remapId: :class:`int`
        The number of the remap. Remaps are numbered in component order, from 0

    boneCount: :class:`int`
        The number of distinct bones the component uses

    Attributes
    ----------
    componentIndex: :class:`int`
        The number of the component that the remap is for

    remapId: :class:`int`
        The number of the remap. Remaps are numbered in component order, from 0

    boneCount: :class:`int`
        The number of distinct bones the component uses
    """

    def __init__(self, componentIndex: int, remapId: int, boneCount: int):
        self.componentIndex = componentIndex
        self.remapId = remapId
        self.boneCount = boneCount

    def __eq__(self, other) -> bool:
        if (not isinstance(other, WWMIBlendRemap)):
            return NotImplemented
        return (self.componentIndex, self.remapId, self.boneCount) == (other.componentIndex, other.remapId, other.boneCount)

    def __repr__(self) -> str:
        return f"WWMIBlendRemap(componentIndex = {self.componentIndex}, remapId = {self.remapId}, boneCount = {self.boneCount})"


class WWMIIniBuilder():
    """
    Writes the ``mod.ini`` of a WWMI identity mod, in the WWMI BETA-2 layout that WWMI Tools 1.3.4 generates
    (for WWMI 0.91 or newer)

    Parameters
    ----------
    name: :class:`str`
        The name of the character

    author: :class:`str`
        The mod author that WWMI shows

    metadata: Dict[:class:`str`, Any]
        The asset folder's ``Metadata.json``

    components: List[:class:`WWMIDrawRange`]
        The components of the character, in order

    shapeKeyCount: :class:`int`
        The number of (shape key, vertex) entries of the mod's shape keys

    textures: List[Tuple[:class:`str`, :class:`str`]]
        The file name of each texture in the mod's ``Textures`` folder and the hash the game binds it under

    blendStride: :class:`int`
        The number of bytes of one vertex in the Blend buffer :raw-html:`<br />` :raw-html:`<br />`

        **Default**: 8

    blendRemaps: List[:class:`WWMIBlendRemap`]
        The blend remaps of the mod, if its merged skeleton needs them :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``[]``

    weightsPerVertex: :class:`int`
        The number of bone weights of one vertex :raw-html:`<br />` :raw-html:`<br />`

        **Default**: 4

    Attributes
    ----------
    name: :class:`str`
        The name of the character

    author: :class:`str`
        The mod author that WWMI shows

    metadata: Dict[:class:`str`, Any]
        The asset folder's ``Metadata.json``

    components: List[:class:`WWMIDrawRange`]
        The components of the character, in order

    shapeKeyCount: :class:`int`
        The number of (shape key, vertex) entries of the mod's shape keys

    textures: List[Tuple[:class:`str`, :class:`str`]]
        The file name of each texture in the mod's ``Textures`` folder and the hash the game binds it under

    blendStride: :class:`int`
        The number of bytes of one vertex in the Blend buffer

    blendRemaps: List[:class:`WWMIBlendRemap`]
        The blend remaps of the mod

    weightsPerVertex: :class:`int`
        The number of bone weights of one vertex
    """

    def __init__(self, name: str, author: str, metadata: Dict[str, Any], components: List[WWMIDrawRange], shapeKeyCount: int,
                 textures: List[Tuple[str, str]], blendStride: int = 8, blendRemaps: List[WWMIBlendRemap] = None, weightsPerVertex: int = 4):
        self.name = name
        self.author = author
        self.metadata = metadata
        self.components = components
        self.shapeKeyCount = shapeKeyCount
        self.textures = textures
        self.blendStride = blendStride
        self.blendRemaps = [] if (blendRemaps is None) else blendRemaps
        self.weightsPerVertex = weightsPerVertex

    @property
    def vertexCount(self) -> int:
        """
        The number of vertices of the whole mesh

        :getter: Retrieves the vertex count
        :type: :class:`int`
        """

        return sum(component.vertexCount for component in self.components)

    @property
    def indexCount(self) -> int:
        """
        The number of indices of the whole mesh

        :getter: Retrieves the index count
        :type: :class:`int`
        """

        return sum(component.indexCount for component in self.components)

    def _buildBlendRemapLines(self) -> List[str]:
        # the blend remap's own sections (WWMI Tools' merged.ini.j2 for blend_remap_count > 0)
        L = ["[ResourceMergedSkeletonRemap]", "[ResourceExtraMergedSkeletonRemap]", "", "[ResourceBlendBufferOverride]", "[ResourceExtraMergedSkeletonOverride]",
             "[ResourceMergedSkeletonOverride]", "", "[ResourceRemappedBlendBufferRW]", "[ResourceRemappedSkeletonRW]", "[ResourceExtraRemappedSkeletonRW]", ""]

        for remap in self.blendRemaps:
            i = remap.componentIndex
            L += [f"[ResourceRemappedBlendBufferComponent{i}]", f"[ResourceRemappedSkeletonComponent{i}]", f"[ResourceExtraRemappedSkeletonComponent{i}]", ""]

        L += ["[CommandListInitializeBlendRemaps]", "local $blend_remaps_initialized", "if !$blend_remaps_initialized",
              "    ResourceRemappedSkeletonRW = copy ResourceMergedSkeletonRW", "    ResourceExtraRemappedSkeletonRW = copy ResourceExtraMergedSkeletonRW",
              "    $\\WWMIv1\\custom_vertex_count = $mesh_vertex_count", f"    $\\WWMIv1\\weights_per_vertex_count = {self.weightsPerVertex}",
              "    cs-t34 = ref ResourceBlendRemapReverseBuffer", "    cs-t35 = ref ResourceBlendRemapVertexVGBuffer"]

        for remap in self.blendRemaps:
            i = remap.componentIndex
            L += [f"    $\\WWMIv1\\blend_remap_id = {remap.remapId}", "    ResourceRemappedBlendBufferRW = copy ResourceBlendBufferNoStride", "    cs-u4 = ref ResourceRemappedBlendBufferRW",
                  "    run = CustomShader\\WWMIv1\\BlendRemapper", f"    ResourceRemappedBlendBufferComponent{i} = copy ResourceRemappedBlendBufferRW",
                  f"    ResourceRemappedBlendBufferComponent{i} = copy_desc ResourceBlendBuffer"]

        L += ["    $blend_remaps_initialized = 1", "endif", ""]
        L += ["[CommandListRemapMergedSkeleton]", "ResourceMergedSkeletonRemap = copy ResourceMergedSkeletonRW", "ResourceExtraMergedSkeletonRemap = copy ResourceExtraMergedSkeletonRW",
              "cs-t37 = ResourceBlendRemapForwardBuffer"]

        for remap in self.blendRemaps:
            i = remap.componentIndex
            L += [f"$\\WWMIv1\\blend_remap_id = {remap.remapId}", f"$\\WWMIv1\\vg_count = {remap.boneCount}", "cs-t38 = ResourceMergedSkeletonRemap", "cs-u5 = ResourceRemappedSkeletonRW",
                  "run = CustomShader\\WWMIv1\\SkeletonRemapper", f"ResourceRemappedSkeletonComponent{i} = copy ResourceRemappedSkeletonRW",
                  "cs-t38 = ResourceExtraMergedSkeletonRemap", "cs-u5 = ResourceExtraRemappedSkeletonRW", "run = CustomShader\\WWMIv1\\SkeletonRemapper",
                  f"ResourceExtraRemappedSkeletonComponent{i} = copy ResourceExtraRemappedSkeletonRW"]

        return L + [""]

    def build(self) -> str:
        """
        Writes the text of the ``mod.ini``

        Returns
        -------
        :class:`str`
            The text, with ``\\n`` line endings
        """

        metadata = self.metadata
        sk = metadata.get("shapekeys") or {}
        remaps = self.blendRemaps
        remapped = {remap.componentIndex for remap in remaps}
        name = self.name

        L = []
        L += ["; WWMI BETA-2 INI", "", "; Mod State -------------------------", "", "[Constants]",
              "global $required_wwmi_version = 0.91", f"global $object_guid = {self.indexCount}", f"global $mesh_vertex_count = {self.vertexCount}",
              f"global $shapekey_vertex_count = {self.shapeKeyCount}", "global $mod_id = -1000", "global $state_id = 0", "global $mod_enabled = 0", "global $object_detected = 0", ""]
        L += ["[Present]", "if $object_detected", "    if $mod_enabled", "        post $object_detected = 0"] + (["        run = CommandListInitializeBlendRemaps"] if remaps else []) + [
              "        run = CommandListUpdateMergedSkeleton", "    else",
              "        if $mod_id == -1000", "            run = CommandListRegisterMod", "        endif", "    endif", "endif", ""]
        L += ["[CommandListRegisterMod]", "$\\WWMIv1\\required_wwmi_version = $required_wwmi_version", "$\\WWMIv1\\object_guid = $object_guid",
              "Resource\\WWMIv1\\ModName = ref ResourceModName", "Resource\\WWMIv1\\ModAuthor = ref ResourceModAuthor", "Resource\\WWMIv1\\ModDesc = ref ResourceModDesc",
              "Resource\\WWMIv1\\ModLink = ref ResourceModLink", "Resource\\WWMIv1\\ModLogo = ref ResourceModLogo", "run = CommandList\\WWMIv1\\RegisterMod",
              "$mod_id = $\\WWMIv1\\mod_id", "if $mod_id >= 0", "    $mod_enabled = 1", "endif", ""]
        L += ["[CommandListUpdateMergedSkeleton]", "if $state_id", "    $state_id = 0", "else", "    $state_id = 1", "endif",
              "ResourceMergedSkeleton = copy ResourceMergedSkeletonRW", "ResourceExtraMergedSkeleton = copy ResourceExtraMergedSkeletonRW"] + (
              ["run = CommandListRemapMergedSkeleton"] if remaps else []) + [""]

        if (remaps):
            L += self._buildBlendRemapLines()

        L += ["; Resources: Mod Info -------------------------", "", "[ResourceModName]", "type = Buffer", f'data = "{name} Identity"', "",
              "[ResourceModAuthor]", "type = Buffer", f'data = "{self.author}"', "", "[ResourceModDesc]", "type = Buffer",
              f'data = "The identity mod of {name}: the game\'s own model out of WWMI-Assets, built by AGIDMGen"', "",
              "[ResourceModLink]", "; type = Buffer", '; data = "Empty Mod Link"', "", "[ResourceModLogo]", "; filename = Textures/Logo.dds", ""]
        L += ["; Shading: Draw Call Stacks Processing -------------------------", "", "[TextureOverrideMarkBoneDataCB]", f"hash = {metadata['cb4_hash']}",
              "match_priority = 0", "filter_index = 3381.7777", ""]
        L += ["[CommandListMergeSkeleton]", "$\\WWMIv1\\custom_mesh_scale = 1.00", "cs-cb8 = ref vs-cb4", "cs-u6 = ResourceMergedSkeletonRW",
              "run = CustomShader\\WWMIv1\\SkeletonMerger", "cs-cb8 = ref vs-cb3", "cs-u6 = ResourceExtraMergedSkeletonRW", "run = CustomShader\\WWMIv1\\SkeletonMerger", ""]
        L += ["[CommandListTriggerResourceOverrides]"] + [f"CheckTextureOverride = ps-t{i}" for i in range(8)] + ["CheckTextureOverride = vs-cb3", "CheckTextureOverride = vs-cb4", ""]
        L += ["[CommandListOverrideSharedResources]", "ResourceBypassVB0 = ref vb0", "ib = ResourceIndexBuffer", "vb0 = ResourcePositionBuffer", "vb1 = ResourceVectorBuffer",
              "vb2 = ResourceTexcoordBuffer", "vb3 = ResourceColorBuffer"]

        if (not remaps):
            L += ["vb4 = ResourceBlendBuffer", "if vs-cb3 == 3381.7777", "    vs-cb3 = ResourceExtraMergedSkeleton", "endif",
                  "if vs-cb4 == 3381.7777", "    vs-cb4 = ResourceMergedSkeleton", "endif", ""]
        else:
            # the 1.3.x form; WWMI Tools 1.7.3 nests the vs-cb3 check inside the vs-cb4 one (with an elif
            #   binding vs-cb3 to the MAIN skeleton), for the plain branch too -- this keeps the form of its
            #   template, which renders on WWMI 1.00
            L += ["if ResourceBlendBufferOverride === null", "    vb4 = ResourceBlendBuffer", "    if vs-cb3 == 3381.7777", "        vs-cb3 = ref ResourceExtraMergedSkeleton", "    endif",
                  "    if vs-cb4 == 3381.7777", "        vs-cb4 = ref ResourceMergedSkeleton", "    endif", "else", "    vb4 = ref ResourceBlendBufferOverride",
                  "    if vs-cb3 == 3381.7777", "        vs-cb3 = ref ResourceExtraMergedSkeletonOverride", "    endif", "    if vs-cb4 == 3381.7777",
                  "        vs-cb4 = ref ResourceMergedSkeletonOverride", "    endif", "endif", ""]

        L += ["[CommandListCleanupSharedResources]", "vb0 = ref ResourceBypassVB0"] + (
              ["if ResourceBlendBufferOverride !== null", "    ResourceBlendBufferOverride = null", "    ResourceMergedSkeletonOverride = null",
               "    ResourceExtraMergedSkeletonOverride = null", "endif"] if remaps else []) + [""]

        for component in self.components:
            i = component.index
            L += [f"[TextureOverrideComponent{i}]", f"hash = {metadata['vb0_hash']}", f"match_first_index = {component.indexOffset}", f"match_index_count = {component.indexCount}",
                  "$object_detected = 1", "if $mod_enabled", f"    local $state_id_{i}", f"    if $state_id_{i} != $state_id", f"        $state_id_{i} = $state_id",
                  f"        $\\WWMIv1\\vg_offset = {int(component.entry['vg_offset'])}", f"        $\\WWMIv1\\vg_count = {int(component.entry['vg_count'])}",
                  "        run = CommandListMergeSkeleton", "    endif", "    if ResourceMergedSkeleton !== null", "        handling = skip"] + (
                  [f"        ResourceBlendBufferOverride = ref ResourceRemappedBlendBufferComponent{i}", f"        ResourceMergedSkeletonOverride = ref ResourceRemappedSkeletonComponent{i}",
                   f"        ResourceExtraMergedSkeletonOverride = ref ResourceExtraRemappedSkeletonComponent{i}"] if i in remapped else []) + [
                  "        run = CommandListTriggerResourceOverrides", "        run = CommandListOverrideSharedResources", f"        ; Draw Component {i}",
                  f"        drawindexed = {component.indexCount}, {component.indexOffset}, 0", "        run = CommandListCleanupSharedResources", "    endif", "endif", ""]

        L += ["; Shading: Textures -------------------------", ""]
        for n, (fileName, textureHash) in enumerate(self.textures):
            L += [f"[ResourceTexture{n}]", f"filename = Textures/{fileName}", "", f"[TextureOverrideTexture{n}]", f"hash = {textureHash}", "match_priority = 0",
                  "if $object_detected", f"    this = ResourceTexture{n}", "endif", ""]

        L += ["; Skinning: Shape Keys Override -------------------------", "", "[TextureOverrideShapeKeyOffsets]", f"hash = {sk.get('offsets_hash', '')}", "match_priority = 0",
              "override_byte_stride = 24", "override_vertex_count = $mesh_vertex_count", "", "[TextureOverrideShapeKeyScale]", f"hash = {sk.get('scale_hash', '')}", "match_priority = 0",
              "override_byte_stride = 4", "override_vertex_count = $mesh_vertex_count", ""]
        L += ["[CommandListSetupShapeKeys]", f"$\\WWMIv1\\shapekey_checksum = {sk.get('checksum', 0)}", "cs-t33 = ResourceShapeKeyOffsetBuffer", "cs-u5 = ResourceCustomShapeKeyValuesRW",
              "cs-u6 = ResourceShapeKeyCBRW", "run = CustomShader\\WWMIv1\\ShapeKeyOverrider", ""]
        L += ["[CommandListLoadShapeKeys]", "$\\WWMIv1\\shapekey_vertex_count = $shapekey_vertex_count", "cs-t0 = ResourceShapeKeyVertexIdBuffer", "cs-t1 = ResourceShapeKeyVertexOffsetBuffer",
              "cs-u6 = ResourceShapeKeyCBRW", "run = CustomShader\\WWMIv1\\ShapeKeyLoader", ""]
        L += ["[TextureOverrideShapeKeyLoaderCallback]", f"hash = {sk.get('offsets_hash', '')}", "match_priority = 0", "if $mod_enabled",
              "    if cs == 3381.3333 && ResourceMergedSkeleton !== null", "        handling = skip", "        run = CommandListSetupShapeKeys", "        run = CommandListLoadShapeKeys",
              "    endif", "endif", ""]
        L += ["[CommandListMultiplyShapeKeys]", "$\\WWMIv1\\custom_vertex_count = $mesh_vertex_count", "run = CustomShader\\WWMIv1\\ShapeKeyMultiplier", ""]
        L += ["[TextureOverrideShapeKeyMultiplierCallback]", f"hash = {sk.get('offsets_hash', '')}", "match_priority = 0", "if $mod_enabled",
              "    if cs == 3381.4444 && ResourceMergedSkeleton !== null", "        handling = skip", "        run = CommandListMultiplyShapeKeys", "    endif", "endif", ""]
        L += ["; Resources: Shape Keys Override -------------------------", "", "[ResourceShapeKeyCBRW]", "type = RWBuffer", "format = R32G32B32A32_UINT", "array = 66", "",
              "[ResourceCustomShapeKeyValuesRW]", "type = RWBuffer", "format = R32G32B32A32_FLOAT", "array = 32", ""]

        # 256 bones, 3 float4s each; 512 with a blend remap
        skeletonArray = 1536 if remaps else 768
        L += ["; Resources: Skeleton Override -------------------------", "", "[ResourceMergedSkeleton]", "", "[ResourceMergedSkeletonRW]", "type = RWBuffer",
              "format = R32G32B32A32_FLOAT", f"array = {skeletonArray}", "", "[ResourceExtraMergedSkeleton]", "", "[ResourceExtraMergedSkeletonRW]", "type = RWBuffer",
              "format = R32G32B32A32_FLOAT", f"array = {skeletonArray}", ""]
        L += ["; Resources: Buffers -------------------------", "", "[ResourceBypassVB0]", ""]

        resources = [("ResourceIndexBuffer", "DXGI_FORMAT_R32_UINT", 12, WWMIBuffers.Index), ("ResourcePositionBuffer", "DXGI_FORMAT_R32G32B32_FLOAT", 12, WWMIBuffers.Position),
                     ("ResourceBlendBuffer", "DXGI_FORMAT_R8_UINT", self.blendStride, WWMIBuffers.Blend), ("ResourceVectorBuffer", "DXGI_FORMAT_R8G8B8A8_SNORM", 8, WWMIBuffers.Vector),
                     ("ResourceColorBuffer", "DXGI_FORMAT_R8G8B8A8_UNORM", 4, WWMIBuffers.Color), ("ResourceTexCoordBuffer", "DXGI_FORMAT_R16G16_FLOAT", 16, WWMIBuffers.TexCoord),
                     ("ResourceShapeKeyOffsetBuffer", "DXGI_FORMAT_R32G32B32A32_UINT", 16, WWMIBuffers.ShapeKeyOffset), ("ResourceShapeKeyVertexIdBuffer", "DXGI_FORMAT_R32_UINT", 4, WWMIBuffers.ShapeKeyVertexId),
                     ("ResourceShapeKeyVertexOffsetBuffer", "DXGI_FORMAT_R16_FLOAT", 2, WWMIBuffers.ShapeKeyVertexOffset)]

        if (remaps):
            # no stride on these: a compute shader cannot address a Buffer declared with one
            resources += [("ResourceBlendRemapVertexVGBuffer", "DXGI_FORMAT_R16_UINT", None, WWMIBuffers.BlendRemapVertexVG),
                          ("ResourceBlendRemapForwardBuffer", "DXGI_FORMAT_R16_UINT", None, WWMIBuffers.BlendRemapForward),
                          ("ResourceBlendRemapReverseBuffer", "DXGI_FORMAT_R16_UINT", None, WWMIBuffers.BlendRemapReverse)]

        for section, fmt, stride, buffer in resources:
            L += [f"[{section}]", "type = Buffer", f"format = {fmt}"] + ([f"stride = {stride}"] if stride is not None else []) + [f"filename = Meshes/{buffer.value}", ""]
            if (buffer == WWMIBuffers.Blend and remaps):
                L += ["[ResourceBlendBufferNoStride]", "type = Buffer", f"format = {fmt}", f"filename = Meshes/{buffer.value}", ""]

        L += ["; Autogenerated -------------------------", "", f"; This mod.ini is the IDENTITY mod of {name}, generated by AGIDMGen (Anime Game Identity Mod Generator) from WWMI-Assets, "
              "in the shape WWMI Tools 1.3.4 generates (WWMI v0.9.1+)", ""]

        return "\n".join(L)


class FmtFile():
    """
    Class for a ``.fmt`` file: the layout of a vertex buffer, as 3DMigoto writes it beside a buffer
    in a frame dump

    .. code-block::

        stride: 48
        topology: trianglelist
        format: DXGI_FORMAT_R16_UINT
        element[0]:
          SemanticName: POSITION
          SemanticIndex: 0
          Format: R32G32B32_FLOAT
          AlignedByteOffset: 0
          ...

    Parameters
    ----------
    header: Optional[Dict[:class:`str`, :class:`str`]]
        The top-level keys of the file (``stride``, ``topology``, ``format``) :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    elements: Optional[List[Dict[:class:`str`, :class:`str`]]]
        The keys of each ``element[N]`` of the file, in order :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Attributes
    ----------
    header: Dict[:class:`str`, :class:`str`]
        The top-level keys of the file (``stride``, ``topology``, ``format``)

    elements: List[Dict[:class:`str`, :class:`str`]]
        The keys of each ``element[N]`` of the file, in order
    """

    def __init__(self, header: Optional[Dict[str, str]] = None, elements: Optional[List[Dict[str, str]]] = None):
        self.header = {} if (header is None) else header
        self.elements = [] if (elements is None) else elements

    @classmethod
    def fromTxt(cls, txt: str):
        """
        Reads a ``.fmt`` file's text

        Parameters
        ----------
        txt: :class:`str`
            The text of the file

        Returns
        -------
        :class:`FmtFile`
            The file read
        """

        header = {}
        elements = []
        current = None

        for line in txt.splitlines():
            if (not line.strip()):
                continue

            if (line.startswith("element[")):
                current = {}
                elements.append(current)
                continue

            key, separator, value = line.partition(":")
            if (not separator):
                continue

            if (line[0] in " \t" and current is not None):
                current[key.strip()] = value.strip()
            else:
                header[key.strip()] = value.strip()

        return cls(header = header, elements = elements)

    @classmethod
    def read(cls, path: str):
        """
        Reads a ``.fmt`` file

        Parameters
        ----------
        path: :class:`str`
            The path to the file

        Returns
        -------
        :class:`FmtFile`
            The file read
        """

        with open(path, "r", encoding = FileEncodings.UTF8.value) as f:
            return cls.fromTxt(f.read())

    @property
    def stride(self) -> int:
        """
        The number of bytes of one vertex in the buffer, or 0 if the file declares none

        :getter: Retrieves the stride
        :type: :class:`int`
        """

        return int(self.header.get("stride", "0"))

    def getElement(self, semanticName: str, semanticIndex: int = 0) -> Optional[Dict[str, str]]:
        """
        Retrieves an element of the buffer

        Parameters
        ----------
        semanticName: :class:`str`
            The semantic name of the element (eg. ``POSITION``), in any case

        semanticIndex: :class:`int`
            The semantic index of the element :raw-html:`<br />` :raw-html:`<br />`

            **Default**: 0

        Returns
        -------
        Optional[Dict[:class:`str`, :class:`str`]]
            The element, or ``None`` if the buffer has no such element
        """

        semanticName = semanticName.upper()
        for element in self.elements:
            if (element.get("SemanticName", "").upper() == semanticName and int(element.get("SemanticIndex", "0")) == semanticIndex):
                return element

        return None


class UnknownDXGIFormat(Error):
    """
    Exception when a buffer element is declared with a DXGI format that cannot be decoded

    Parameters
    ----------
    format: :class:`str`
        The name of the format

    Attributes
    ----------
    format: :class:`str`
        The name of the format
    """

    def __init__(self, format: str):
        super().__init__(f"The format '{format}' cannot be decoded (the formats known are: {', '.join(sorted(DXGIFormats))})")
        self.format = format


class FormatTools():
    """
    Tools for handling the DXGI formats of buffer elements
    """

    @classmethod
    def decode(cls, format: str) -> Tuple[str, int]:
        """
        Retrieves how an element of some DXGI format is decoded

        Parameters
        ----------
        format: :class:`str`
            The name of the format, with or without the ``DXGI_FORMAT_`` prefix (eg. ``R32G32B32_FLOAT`` or ``DXGI_FORMAT_R32G32B32_FLOAT``)

        Raises
        ------
        :class:`UnknownDXGIFormat`
            If the format cannot be decoded

        Returns
        -------
        Tuple[:class:`str`, :class:`int`]
            The numpy dtype of one channel and the number of channels
        """

        key = format.strip().upper()
        if (key.startswith(DXGIFormatPrefix)):
            key = key[len(DXGIFormatPrefix):]

        try:
            return DXGIFormats[key]
        except KeyError:
            raise UnknownDXGIFormat(format) from None


class WWMIComponent(WWMIDrawRange):
    """
    Class for one ``Component N`` of a WuWa character's asset folder: one draw range of the
    character's mesh, with its own interleaved vertex buffer (``Component N.vb``), its layout
    (``Component N.fmt``) and its index buffer (``Component N.ib``)

    Parameters
    ----------
    folder: :class:`str`
        The asset folder

    index: :class:`int`
        The number of the component

    entry: Dict[:class:`str`, Any]
        The component's entry in the ``components`` list of the asset folder's ``Metadata.json``

    Raises
    ------
    :class:`BadAssetData`
        If one of the component's files is missing, or its files disagree with each other or with ``entry``

    Attributes
    ----------
    index: :class:`int`
        The number of the component

    entry: Dict[:class:`str`, Any]
        The component's entry in the ``components`` list of the asset folder's ``Metadata.json``

    fmt: :class:`FmtFile`
        The layout of the component's vertex buffer

    rows: numpy.ndarray
        The component's vertex buffer, one row of bytes per vertex

    indices: numpy.ndarray
        The component's indices (local to the component), as ``uint32``

    vertexOffset: :class:`int`
        Where the component's vertices start in the whole mesh

    indexOffset: :class:`int`
        Where the component's indices start in the whole mesh's index buffer
    """

    def __init__(self, folder: str, index: int, entry: Dict[str, Any]):
        super().__init__(index, entry)

        base = os.path.join(folder, f"Component {index}")
        for ext in (".fmt", ".vb", ".ib"):
            if (not os.path.isfile(base + ext)):
                raise BadAssetData(f"'{base + ext}' is missing for component {index} of Metadata.json")

        self.fmt = FmtFile.read(base + ".fmt")
        stride = self.stride
        raw = np.fromfile(base + ".vb", dtype = np.uint8)
        if (stride <= 0 or raw.size % stride != 0):
            raise BadAssetData(f"'Component {index}.vb' is {raw.size} bytes, not a whole number of {stride}-byte vertices")

        self.rows = raw.reshape(-1, stride)
        vertexCount = self.vertexCount
        if (int(entry.get("vertex_count", vertexCount)) != vertexCount):
            raise BadAssetData(f"'Component {index}.vb' holds {vertexCount} vertices but Metadata.json declares {entry.get('vertex_count')}")

        ibDtype, _ = FormatTools.decode(self.fmt.header.get("format", "R16_UINT"))
        self.indices = np.fromfile(base + ".ib", dtype = ibDtype).astype(np.uint32)
        if (int(entry.get("index_count", self.indices.size)) != self.indices.size):
            raise BadAssetData(f"'Component {index}.ib' holds {self.indices.size} indices but Metadata.json declares {entry.get('index_count')}")

        if (self.indices.size and int(self.indices.max()) >= vertexCount):
            raise BadAssetData(f"'Component {index}.ib' references vertex {int(self.indices.max())} of {vertexCount}")

    @property
    def stride(self) -> int:
        """
        The number of bytes of one vertex in the component's vertex buffer

        :getter: Retrieves the stride
        :type: :class:`int`
        """

        return self.fmt.stride

    @property
    def vertexCount(self) -> int:
        """
        The number of vertices in the component

        :getter: Retrieves the vertex count
        :type: :class:`int`
        """

        return self.rows.shape[0]

    @property
    def indexCount(self) -> int:
        """
        The number of indices in the component

        :getter: Retrieves the index count
        :type: :class:`int`
        """

        return int(self.indices.size)

    def hasElement(self, semanticName: str, semanticIndex: int = 0) -> bool:
        """
        Whether the component's vertex buffer has some element

        Parameters
        ----------
        semanticName: :class:`str`
            The semantic name of the element (eg. ``POSITION``), in any case

        semanticIndex: :class:`int`
            The semantic index of the element :raw-html:`<br />` :raw-html:`<br />`

            **Default**: 0

        Returns
        -------
        :class:`bool`
            Whether the element exists
        """

        return self.fmt.getElement(semanticName, semanticIndex) is not None

    def getElementBytes(self, semanticName: str, semanticIndex: int, width: int) -> np.ndarray:
        """
        Retrieves the first bytes of an element, for every vertex of the component

        .. note::
            A character with eight bone influences a vertex declares its ``BLENDINDICES`` / ``BLENDWEIGHT``
            as a single-channel format while each spans 8 bytes. A single-channel element is therefore as
            wide as the space up to the next element.

        Parameters
        ----------
        semanticName: :class:`str`
            The semantic name of the element (eg. ``POSITION``), in any case

        semanticIndex: :class:`int`
            The semantic index of the element

        width: :class:`int`
            The number of bytes to retrieve per vertex

        Raises
        ------
        :class:`BadAssetData`
            If the component has no such element, or the element is narrower than ``width``

        Returns
        -------
        numpy.ndarray
            The bytes, one row per vertex, as a view of :attr:`rows`
        """

        element = self.fmt.getElement(semanticName, semanticIndex)
        if (element is None):
            raise BadAssetData(f"Component {self.index}: the .fmt declares no {semanticName}{semanticIndex} element")

        dtype, count = FormatTools.decode(element.get("Format", ""))
        offset = int(element.get("AlignedByteOffset", "0"))

        following = [int(e.get("AlignedByteOffset", "0")) for e in self.fmt.elements if int(e.get("AlignedByteOffset", "0")) > offset]
        span = (min(following) if following else self.stride) - offset
        available = max(np.dtype(dtype).itemsize * count, span if count == 1 else 0)
        if (width > available):
            raise BadAssetData(f"Component {self.index}: {semanticName}{semanticIndex} is {available} bytes in the .fmt, {width} wanted")

        return self.rows[:, offset:offset + width]

    def getShapeKeys(self) -> Dict[int, Tuple[np.ndarray, np.ndarray]]:
        """
        Retrieves the shape keys of the component: every ``SHAPEKEY`` element that moves at least one vertex

        Raises
        ------
        :class:`BadAssetData`
            If a ``SHAPEKEY`` element does not have three channels

        Returns
        -------
        Dict[:class:`int`, Tuple[numpy.ndarray, numpy.ndarray]]
            For each shape key, the local ids of the vertices it moves and their position deltas as ``float16`` (one row of 3 per vertex)
        """

        result = {}
        for element in self.fmt.elements:
            if (element.get("SemanticName", "").upper() != "SHAPEKEY"):
                continue

            key = int(element.get("SemanticIndex", "0"))
            dtype, count = FormatTools.decode(element.get("Format", ""))
            if (count != 3):
                raise BadAssetData(f"Component {self.index}: SHAPEKEY{key} is {element.get('Format')}, expected three channels")

            offset = int(element.get("AlignedByteOffset", "0"))
            width = np.dtype(dtype).itemsize * 3
            deltas = np.ascontiguousarray(self.rows[:, offset:offset + width]).view(dtype).reshape(-1, 3)
            used = np.nonzero((deltas != 0).any(axis = 1))[0]
            if (used.size):
                result[key] = (used, deltas[used].astype("<f2"))

        return result


class WWMIShapeKeys():
    """
    Class for the sparse shape keys of a WWMI mod, as WWMI's shape key loader reads them

    Parameters
    ----------
    offsets: numpy.ndarray
        Where each shape key slot's entries start in ``vertexIds`` and ``deltas``, as ``uint32``. A slot past the last shape key holds the total number of entries

    vertexIds: numpy.ndarray
        The vertex of each entry, shape key by shape key, as ``uint32``

    deltas: numpy.ndarray
        Six ``float16`` per entry: the position delta of the entry's vertex, then three zeros

    counts: List[:class:`int`]
        The number of entries of each shape key slot

    Attributes
    ----------
    offsets: numpy.ndarray
        Where each shape key slot's entries start in :attr:`vertexIds` and :attr:`deltas`, as ``uint32``. A slot past the last shape key holds the total number of entries

    vertexIds: numpy.ndarray
        The vertex of each entry, shape key by shape key, as ``uint32``

    deltas: numpy.ndarray
        Six ``float16`` per entry: the position delta of the entry's vertex, then three zeros

    counts: List[:class:`int`]
        The number of entries of each shape key slot
    """

    def __init__(self, offsets: np.ndarray, vertexIds: np.ndarray, deltas: np.ndarray, counts: List[int]):
        self.offsets = offsets
        self.vertexIds = vertexIds
        self.deltas = deltas
        self.counts = counts

    @property
    def entryCount(self) -> int:
        """
        The number of (shape key, vertex) entries

        :getter: Retrieves the number of entries
        :type: :class:`int`
        """

        return int(self.vertexIds.size)

    @property
    def keys(self) -> List[int]:
        """
        The shape keys that move at least one vertex, in order

        :getter: Retrieves the shape keys
        :type: List[:class:`int`]
        """

        return [key for key, count in enumerate(self.counts) if count]

    @property
    def checksum(self) -> int:
        """
        The sum of the first four offsets: the number the game's ``Metadata.json`` records as the shape keys' ``checksum``

        :getter: Retrieves the checksum
        :type: :class:`int`
        """

        return int(self.offsets[:4].sum())

    @property
    def dispatchY(self) -> int:
        """
        The number of entries in groups of 32, rounded up: the number the game's ``Metadata.json`` records as the shape keys' ``dispatch_y``

        :getter: Retrieves the dispatch count
        :type: :class:`int`
        """

        return -(-self.entryCount // 32)


class WWMIMesh():
    """
    Class for a WuWa character's mesh, as a WWMI mod carries it: the contents of every buffer of
    the mod's ``Meshes`` folder, and what the mod's ``mod.ini`` needs to know about them

    Parameters
    ----------
    metadata: Dict[:class:`str`, Any]
        The character's ``Metadata.json``

    drawRanges: List[:class:`WWMIDrawRange`]
        Where each component lies in the mesh, in order

    buffers: Dict[:class:`WWMIBuffers`, :class:`bytes`]
        The contents of each buffer

    shapeKeys: :class:`WWMIShapeKeys`
        The shape keys of the mesh

    blendRemaps: List[:class:`WWMIBlendRemap`]
        The blend remaps of the mesh, if its merged skeleton needs them

    blendStride: :class:`int`
        The number of bytes of one vertex in the Blend buffer

    weightsPerVertex: :class:`int`
        The number of bone weights of one vertex

    highestBone: :class:`int`
        The highest merged bone index a vertex refers to

    Attributes
    ----------
    metadata: Dict[:class:`str`, Any]
        The character's ``Metadata.json``

    drawRanges: List[:class:`WWMIDrawRange`]
        Where each component lies in the mesh, in order

    buffers: Dict[:class:`WWMIBuffers`, :class:`bytes`]
        The contents of each buffer

    shapeKeys: :class:`WWMIShapeKeys`
        The shape keys of the mesh

    blendRemaps: List[:class:`WWMIBlendRemap`]
        The blend remaps of the mesh

    blendStride: :class:`int`
        The number of bytes of one vertex in the Blend buffer

    weightsPerVertex: :class:`int`
        The number of bone weights of one vertex

    highestBone: :class:`int`
        The highest merged bone index a vertex refers to
    """

    def __init__(self, metadata: Dict[str, Any], drawRanges: List[WWMIDrawRange], buffers: Dict[WWMIBuffers, bytes], shapeKeys: WWMIShapeKeys,
                 blendRemaps: List[WWMIBlendRemap], blendStride: int, weightsPerVertex: int, highestBone: int):
        self.metadata = metadata
        self.drawRanges = drawRanges
        self.buffers = buffers
        self.shapeKeys = shapeKeys
        self.blendRemaps = blendRemaps
        self.blendStride = blendStride
        self.weightsPerVertex = weightsPerVertex
        self.highestBone = highestBone


class WWMIIdentityMod():
    """
    Class for a generated WWMI identity mod: what was written, and the numbers that show whether it
    reads the character the way the game does

    Parameters
    ----------
    name: :class:`str`
        The name of the character

    folder: :class:`str`
        The folder the mod was written into

    metadata: Dict[:class:`str`, Any]
        The asset folder's ``Metadata.json``

    components: List[:class:`WWMIDrawRange`]
        The components of the character, in order

    shapeKeys: :class:`WWMIShapeKeys`
        The shape keys of the mod

    blendRemaps: List[:class:`WWMIBlendRemap`]
        The blend remaps of the mod

    weightsPerVertex: :class:`int`
        The number of bone weights of one vertex

    blendStride: :class:`int`
        The number of bytes of one vertex in the Blend buffer

    highestBone: :class:`int`
        The highest merged bone index a vertex refers to

    bufferSizes: Dict[:class:`WWMIBuffers`, :class:`int`]
        The size in bytes of each buffer file written

    textures: List[Tuple[:class:`str`, :class:`str`]]
        The file name of each texture in the mod's ``Textures`` folder and the hash the game binds it under

    Attributes
    ----------
    name: :class:`str`
        The name of the character

    folder: :class:`str`
        The folder the mod was written into

    metadata: Dict[:class:`str`, Any]
        The asset folder's ``Metadata.json``

    components: List[:class:`WWMIDrawRange`]
        The components of the character, in order

    shapeKeys: :class:`WWMIShapeKeys`
        The shape keys of the mod

    blendRemaps: List[:class:`WWMIBlendRemap`]
        The blend remaps of the mod

    weightsPerVertex: :class:`int`
        The number of bone weights of one vertex

    blendStride: :class:`int`
        The number of bytes of one vertex in the Blend buffer

    highestBone: :class:`int`
        The highest merged bone index a vertex refers to

    bufferSizes: Dict[:class:`WWMIBuffers`, :class:`int`]
        The size in bytes of each buffer file written

    textures: List[Tuple[:class:`str`, :class:`str`]]
        The file name of each texture in the mod's ``Textures`` folder and the hash the game binds it under
    """

    def __init__(self, name: str, folder: str, metadata: Dict[str, Any], components: List[WWMIDrawRange], shapeKeys: WWMIShapeKeys,
                 blendRemaps: List[WWMIBlendRemap], weightsPerVertex: int, blendStride: int, highestBone: int,
                 bufferSizes: Dict[WWMIBuffers, int], textures: List[Tuple[str, str]]):
        self.name = name
        self.folder = folder
        self.metadata = metadata
        self.components = components
        self.shapeKeys = shapeKeys
        self.blendRemaps = blendRemaps
        self.weightsPerVertex = weightsPerVertex
        self.blendStride = blendStride
        self.highestBone = highestBone
        self.bufferSizes = bufferSizes
        self.textures = textures

    @property
    def vertexCount(self) -> int:
        """
        The number of vertices of the whole mesh

        :getter: Retrieves the vertex count
        :type: :class:`int`
        """

        return sum(component.vertexCount for component in self.components)

    @property
    def indexCount(self) -> int:
        """
        The number of indices of the whole mesh

        :getter: Retrieves the index count
        :type: :class:`int`
        """

        return sum(component.indexCount for component in self.components)

    @property
    def checksumMatches(self) -> Optional[bool]:
        """
        Whether the shape keys' checksum is the one the asset folder's ``Metadata.json`` records, or ``None`` if it records none

        :getter: Retrieves whether the checksums match
        :type: Optional[:class:`bool`]
        """

        expected = (self.metadata.get("shapekeys") or {}).get("checksum")
        return None if (expected is None) else (self.shapeKeys.checksum == int(expected))

    @property
    def dispatchYMatches(self) -> Optional[bool]:
        """
        Whether the shape keys' dispatch count is the one the asset folder's ``Metadata.json`` records, or ``None`` if it records none

        :getter: Retrieves whether the dispatch counts match
        :type: Optional[:class:`bool`]
        """

        expected = (self.metadata.get("shapekeys") or {}).get("dispatch_y")
        return None if (expected is None) else (self.shapeKeys.dispatchY == int(expected))

    def getSummary(self) -> List[str]:
        """
        Describes the mod: its components, buffers, blend, shape keys and textures

        Returns
        -------
        List[:class:`str`]
            The lines of the description
        """

        metadata = self.metadata
        sk = metadata.get("shapekeys") or {}
        shapeKeys = self.shapeKeys
        vertexCount = self.vertexCount
        indexCount = self.indexCount

        lines = [f"{self.name}: {len(self.components)} components, {vertexCount} vertices, {indexCount} indices ({indexCount // 3} triangles), hash {metadata.get('vb0_hash')}, skeleton cb4 {metadata.get('cb4_hash')}"]
        for component in self.components:
            vgMap = component.entry.get("vg_map") or {}
            vgOffset = int(component.entry.get("vg_offset", 0))
            borrowed = sum(1 for k, v in vgMap.items() if int(v) != vgOffset + int(k))
            lines.append(f"  Component {component.index}: {component.vertexCount} vertices from {component.vertexOffset}, {component.indexCount} indices from {component.indexOffset}, "
                         f"{int(component.entry.get('vg_count', 0))} bones at merged slot {vgOffset}" + (f" ({borrowed} of them another component's)" if (vgMap) else ""))

        lines.append("  buffers: " + ", ".join(f"{buffer.value} {self.bufferSizes[buffer]} B" for buffer in WWMIBuffers if buffer in self.bufferSizes))
        lines.append(f"  blend: {self.weightsPerVertex} bones a vertex ({self.blendStride} B), highest merged bone {self.highestBone}; "
                     + (f"blend remaps for components {', '.join(f'{r.componentIndex} (remap {r.remapId}, {r.boneCount} bones)' for r in self.blendRemaps)}" if self.blendRemaps else "no blend remap needed"))

        keys = shapeKeys.keys
        keyRange = f"{keys[0]}-{keys[-1]}" if (keys) else "none"
        checksumMatches = self.checksumMatches
        dispatchYMatches = self.dispatchYMatches
        lines.append(f"  shape keys: {len(keys)} keys ({keyRange}), {shapeKeys.entryCount} (key, vertex) entries; first offsets {shapeKeys.offsets[:4].tolist()} sum {shapeKeys.checksum} "
                     f"vs Metadata checksum {sk.get('checksum')} ({'OK' if checksumMatches else 'MISMATCH'}); dispatch_y {shapeKeys.dispatchY} vs {sk.get('dispatch_y')} "
                     f"({'OK' if dispatchYMatches else 'MISMATCH'}); entries vs Metadata {sk.get('vertex_count')}")
        lines.append(f"  textures: {len(self.textures)}" + ("" if self.textures else " (none)"))
        lines.append(f"  written to {self.folder}")
        return lines


#: The file names of an asset folder's textures: ``Components-<components> t=<hash>.dds``, named by the components that use them and the hash the game binds them under
WWMITexturePattern = re.compile(r"^Components-[0-9-]+ t=(?P<hash>[0-9a-fA-F]{8})\.dds$")


class WWMIIdentityModGenerator(Model):
    """
    Generates the identity mod of a WuWa character: the game's own model, written out as a
    WWMI mod from the character's asset folder

    The asset folder is laid out as `WWMI-Assets <https://github.com/SpectrumQT/WWMI-Assets>`_'s
    ``PlayerCharacterData/<Name>`` folders are:

    - ``Metadata.json``, with the mesh's hashes, its components and the layout of the mod's buffers (``export_format``)
    - ``Component N.fmt``, ``Component N.vb`` and ``Component N.ib`` for each component
    - the textures, named ``Components-<components> t=<hash>.dds``

    The mod is written as:

    - ``mod.ini``
    - ``Meshes/``: the buffers of :class:`WWMIBuffers` (the blend remap buffers only for a character whose merged skeleton needs them)
    - ``Textures/``: every texture of the asset folder

    Examples
    --------
    .. code-block:: python
        :linenos:

        import AGIDMGen as IDMG

        generator = IDMG.WWMIIdentityModGenerator()
        mod = generator.generate("WWMI-Assets/PlayerCharacterData/Sanhua", "Mods/SanhuaIdentity")
        print("\\n".join(mod.getSummary()))

    Parameters
    ----------
    author: :class:`str`
        The mod author that WWMI shows :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``"Anime Game Remap"``

    includeTextures: :class:`bool`
        Whether to copy the textures into the mod :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``True``

    useVgMap: :class:`bool`
        Whether to write each bone index through its component's ``vg_map`` (the bone indices every real mod uses), rather than as the component's ``vg_offset`` plus the local index (which points into the merged skeleton's duplicate slots) :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``True``

    logger: Optional[:class:`BaseLogger`]
        Where to report what is done. If this value is ``None``, nothing is reported :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Attributes
    ----------
    author: :class:`str`
        The mod author that WWMI shows

    includeTextures: :class:`bool`
        Whether to copy the textures into the mod

    useVgMap: :class:`bool`
        Whether to write each bone index through its component's ``vg_map``
    """

    def __init__(self, author: str = "Anime Game Remap", includeTextures: bool = True, useVgMap: bool = True, logger: Optional[BaseLogger] = None):
        super().__init__(logger = logger)
        self.author = author
        self.includeTextures = includeTextures
        self.useVgMap = useVgMap

    @classmethod
    def readMetadata(cls, assetsFolder: str) -> Dict[str, Any]:
        """
        Reads the ``Metadata.json`` of an asset folder

        Parameters
        ----------
        assetsFolder: :class:`str`
            The asset folder

        Raises
        ------
        :class:`BadAssetData`
            If the asset folder has no ``Metadata.json``

        Returns
        -------
        Dict[:class:`str`, Any]
            The metadata
        """

        path = os.path.join(assetsFolder, "Metadata.json")
        if (not os.path.isfile(path)):
            raise BadAssetData(f"'{path}' is missing")

        with open(path, "r", encoding = FileEncodings.UTF8.value) as f:
            return json.load(f)

    @classmethod
    def readComponents(cls, assetsFolder: str, metadata: Dict[str, Any]) -> List[WWMIComponent]:
        """
        Reads the components of an asset folder, and checks that they lie end to end in the order ``Metadata.json`` lists them

        Parameters
        ----------
        assetsFolder: :class:`str`
            The asset folder

        metadata: Dict[:class:`str`, Any]
            The asset folder's ``Metadata.json``

        Raises
        ------
        :class:`BadAssetData`
            If ``Metadata.json`` lists no components, a component's files are missing or wrong, or the components' offsets or totals disagree with ``Metadata.json``

        Returns
        -------
        List[:class:`WWMIComponent`]
            The components, in order
        """

        components = [WWMIComponent(assetsFolder, i, entry) for i, entry in enumerate(metadata.get("components") or [])]
        cls.checkDrawRanges(components, metadata, assetsFolder)
        return components

    @classmethod
    def checkDrawRanges(cls, drawRanges: List[WWMIDrawRange], metadata: Dict[str, Any], folder: str):
        """
        Checks that the components lie end to end in the order ``Metadata.json`` lists them, and add up to its totals

        Parameters
        ----------
        drawRanges: List[:class:`WWMIDrawRange`]
            The components, in order

        metadata: Dict[:class:`str`, Any]
            The ``Metadata.json``

        folder: :class:`str`
            The folder the components were read from, for the error messages

        Raises
        ------
        :class:`BadAssetData`
            If there are no components, or their offsets or totals disagree with ``Metadata.json``
        """

        if (not drawRanges):
            raise BadAssetData(f"'{folder}': Metadata.json lists no components")

        vertexOffset = 0
        indexOffset = 0
        for drawRange in drawRanges:
            if (drawRange.vertexOffset != vertexOffset or drawRange.indexOffset != indexOffset):
                raise BadAssetData(f"Component {drawRange.index}: Metadata's offsets ({drawRange.vertexOffset}, {drawRange.indexOffset}) do not follow the previous components ({vertexOffset}, {indexOffset})")
            vertexOffset += drawRange.vertexCount
            indexOffset += drawRange.indexCount

        if (int(metadata.get("vertex_count", vertexOffset)) != vertexOffset or int(metadata.get("index_count", indexOffset)) != indexOffset):
            raise BadAssetData(f"'{folder}': the components total {vertexOffset} vertices / {indexOffset} indices but Metadata.json says {metadata.get('vertex_count')} / {metadata.get('index_count')}")

    @classmethod
    def getExportSemantics(cls, metadata: Dict[str, Any], buffer: WWMIBuffers) -> List[Tuple[str, int, str, int]]:
        """
        Retrieves the layout of one of the mod's buffers, from the ``export_format`` of ``Metadata.json``

        Parameters
        ----------
        metadata: Dict[:class:`str`, Any]
            The asset folder's ``Metadata.json``

        buffer: :class:`WWMIBuffers`
            The buffer

        Raises
        ------
        :class:`BadAssetData`
            If ``Metadata.json`` has no ``export_format`` for the buffer

        Returns
        -------
        List[Tuple[:class:`str`, :class:`int`, :class:`str`, :class:`int`]]
            The semantic name, semantic index, format and number of bytes of each element of a vertex, in order
        """

        exportFormat = metadata.get("export_format") or {}
        entry = exportFormat.get(buffer.name)
        if (entry is None):
            raise BadAssetData(f"Metadata.json's export_format has no '{buffer.name}' buffer")

        return [(s["name"], int(s.get("index", 0)), s["format"], int(s["stride"])) for s in entry["semantics"]]

    @classmethod
    def buildIndex(cls, components: List[WWMIComponent]) -> np.ndarray:
        """
        Builds the index buffer of the whole mesh: each component's indices, offset by where its vertices start

        Parameters
        ----------
        components: List[:class:`WWMIComponent`]
            The components, in order

        Returns
        -------
        numpy.ndarray
            The indices, as little-endian ``uint32``
        """

        return np.concatenate([component.indices + np.uint32(component.vertexOffset) for component in components]).astype("<u4")

    @classmethod
    def buildVertexBuffer(cls, components: List[WWMIComponent], semantics: List[Tuple[str, int, str, int]]) -> bytes:
        """
        Builds one of the mod's vertex buffers: for every vertex of every component, the listed elements' bytes side by side

        Parameters
        ----------
        components: List[:class:`WWMIComponent`]
            The components, in order

        semantics: List[Tuple[:class:`str`, :class:`int`, :class:`str`, :class:`int`]]
            The layout of the buffer, from :meth:`getExportSemantics`

        Raises
        ------
        :class:`BadAssetData`
            If a component lacks one of the elements

        Returns
        -------
        :class:`bytes`
            The buffer
        """

        parts = []
        for component in components:
            columns = []
            for name, semanticIndex, fmt, stride in semantics:
                if (name.upper() == "BITANGENTSIGN" and not component.hasElement(name, semanticIndex)):
                    # WWMI Tools splits the dump's four-byte NORMAL into a three-byte normal and the
                    #   bitangent sign; the sign is the NORMAL element's fourth byte
                    normal = component.getElementBytes("NORMAL", 0, 4)
                    columns.append(normal[:, 3:4])
                    continue
                columns.append(component.getElementBytes(name, semanticIndex, stride))
            parts.append(np.ascontiguousarray(np.concatenate(columns, axis = 1)))

        return b"".join(part.tobytes() for part in parts)

    def buildBlend(self, components: List[WWMIComponent], semantics: List[Tuple[str, int, str, int]]) -> Tuple[bytes, np.ndarray, np.ndarray]:
        """
        Builds the Blend buffer, with the bone indices sent into the merged skeleton

        .. note::
            A merged bone index of 256 or more is written into the 8-bit Blend buffer truncated, as WWMI Tools does.
            The full indices are returned for :meth:`buildBlendRemaps`.

        Parameters
        ----------
        components: List[:class:`WWMIComponent`]
            The components, in order

        semantics: List[Tuple[:class:`str`, :class:`int`, :class:`str`, :class:`int`]]
            The layout of the Blend buffer, from :meth:`getExportSemantics`

        Raises
        ------
        :class:`BadAssetData`
            If a component uses a bone its ``vg_map`` does not have, or a merged bone index is past WWMI's limit

        Returns
        -------
        Tuple[:class:`bytes`, numpy.ndarray, numpy.ndarray]
            The Blend buffer, the full merged bone indices of every vertex (``uint16``) and the bone weights of every vertex
        """

        parts = []
        allIds = []
        allWeights = []

        for component in components:
            columns = []
            for name, semanticIndex, fmt, stride in semantics:
                data = np.ascontiguousarray(component.getElementBytes(name, semanticIndex, stride)).copy()

                if (name.upper() == "BLENDINDICES"):
                    vgMap = component.entry.get("vg_map") or {}
                    if (self.useVgMap and vgMap):
                        table = np.array([int(vgMap[str(local)]) for local in range(len(vgMap))], dtype = np.int64)
                        if (int(data.max()) >= len(table)):
                            raise BadAssetData(f"Component {component.index} uses bone {int(data.max())} but its vg_map has {len(table)} entries")
                        mapped = table[data.astype(np.int64)]
                    else:
                        mapped = data.astype(np.int64) + int(component.entry.get("vg_offset", 0))

                    if (int(mapped.max()) >= WWMIBlendRemapSize):
                        raise BadAssetData(f"Component {component.index}: a merged bone index of {int(mapped.max())} is past WWMI's {WWMIBlendRemapSize}-bone limit")

                    allIds.append(mapped.astype(np.uint16))
                    data = mapped.astype(np.uint8)

                elif (name.upper() == "BLENDWEIGHT"):
                    allWeights.append(data)

                columns.append(data)
            parts.append(np.ascontiguousarray(np.concatenate(columns, axis = 1)))

        if (not allIds or not allWeights):
            raise BadAssetData("Metadata.json's export_format has no BLENDINDICES or no BLENDWEIGHT in its 'Blend' buffer")

        return b"".join(part.tobytes() for part in parts), np.concatenate(allIds), np.concatenate(allWeights)

    # ---- WWMI's blend remap: a merged skeleton of more than 256 bones ----
    #
    # The Blend buffer's bone indices are 8 bits, and a character whose merged skeleton passes 256 slots
    # (Chisa: 420; WWMI-Assets' Augusta, Iuno, Galbrena) has vertices weighted to bones the byte cannot
    # name. WWMI's answer, as WWMI Tools writes it (blender_export/data_models/data_model_wwmi.py's
    # build_blend_remap, identical in 1.3.3 and 1.7.3 except that 1.3.3 hard-codes four ids a vertex):
    #   * per COMPONENT whose vertices (those its index range reaches) carry a non-zero weight on a bone
    #     >= 256, a remap: the sorted distinct bones it uses (at most 256) get local ids 0..n-1;
    #     'BlendRemapForward.buf' holds 512 uint16s per remap, local -> merged, and
    #     'BlendRemapReverse.buf' 512 per remap, merged -> local. Remaps are numbered in component order.
    #   * 'BlendRemapVertexVG.buf' holds every vertex's FULL merged ids as uint16s, as many a vertex as
    #     the Blend buffer has weights (8 for Chisa).
    #   * at load, WWMI's BlendRemapper.hlsl writes a copy of Blend.buf per remapped component with each
    #     id replaced by reverse[full id]; each frame SkeletonRemapper.hlsl builds that component's own
    #     skeleton by gathering forward[local] out of the merged one; the component's draw binds both.
    #     The merged skeleton buffers grow to 512 bones (array = 1536).
    # The Blend.buf bytes themselves stay the merged ids truncated to 8 bits -- what a component with no
    # remap reads, correctly, since its ids are all below 256.
    @classmethod
    def buildBlendRemaps(cls, components: List[WWMIDrawRange], ids: np.ndarray, weights: np.ndarray, indexBuffer: np.ndarray) -> Tuple[List[WWMIBlendRemap], Optional[np.ndarray], Optional[np.ndarray]]:
        """
        Builds the blend remaps of the components that weight a merged bone past the 256 the Blend buffer can name

        Parameters
        ----------
        components: List[:class:`WWMIDrawRange`]
            The components, in order

        ids: numpy.ndarray
            The full merged bone indices of every vertex, from :meth:`buildBlend`

        weights: numpy.ndarray
            The bone weights of every vertex, from :meth:`buildBlend`

        indexBuffer: numpy.ndarray
            The index buffer of the whole mesh, from :meth:`buildIndex`

        Raises
        ------
        :class:`BadAssetData`
            If a component weights more distinct bones than one remap can hold

        Returns
        -------
        Tuple[List[:class:`WWMIBlendRemap`], Optional[numpy.ndarray], Optional[numpy.ndarray]]
            The remaps, then the forward and reverse tables of every remap laid end to end (``uint16``), or ``None`` for both if no component needs a remap
        """

        remaps = []
        forward = []
        reverse = []

        for component in components:
            vertexIds = np.unique(indexBuffer[component.indexOffset:component.indexOffset + component.indexCount])
            used = ids[vertexIds].ravel()
            if (used.size == 0 or int(used.max()) < WWMIBlendIndexLimit):
                continue

            used = np.unique(used[weights[vertexIds].ravel() > 0])
            if (used.size == 0 or int(used.max()) < WWMIBlendIndexLimit):
                continue

            if (used.size > WWMIBlendIndexLimit):
                raise BadAssetData(f"Component {component.index} weights {used.size} distinct bones, past the {WWMIBlendIndexLimit} one remap can hold")

            f = np.zeros(WWMIBlendRemapSize, dtype = "<u2")
            f[np.arange(used.size)] = used
            r = np.zeros(WWMIBlendRemapSize, dtype = "<u2")
            r[used] = np.arange(used.size)

            remaps.append(WWMIBlendRemap(component.index, len(remaps), int(used.size)))
            forward.append(f)
            reverse.append(r)

        if (not remaps):
            return [], None, None
        return remaps, np.concatenate(forward), np.concatenate(reverse)

    @classmethod
    def buildShapeKeys(cls, components: List[WWMIComponent]) -> WWMIShapeKeys:
        """
        Builds the sparse shape keys of the mod from the components' ``SHAPEKEY`` elements

        Parameters
        ----------
        components: List[:class:`WWMIComponent`]
            The components, in order

        Raises
        ------
        :class:`BadAssetData`
            If a shape key does not fit WWMI's shape key slots

        Returns
        -------
        :class:`WWMIShapeKeys`
            The shape keys
        """

        perKey = {}
        for component in components:
            for key, (used, deltas) in component.getShapeKeys().items():
                perKey.setdefault(key, []).append((used.astype(np.uint32) + np.uint32(component.vertexOffset), deltas))

        if (perKey and max(perKey) >= WWMIShapeKeySlots - 1):
            raise BadAssetData(f"shape key {max(perKey)} does not fit WWMI's {WWMIShapeKeySlots} slots")

        ids = []
        deltas = []
        counts = [0] * WWMIShapeKeySlots
        for key in sorted(perKey):
            keyIds = np.concatenate([u for u, _ in perKey[key]])
            keyDeltas = np.concatenate([d for _, d in perKey[key]])
            order = np.argsort(keyIds, kind = "stable")
            ids.append(keyIds[order])
            deltas.append(keyDeltas[order])
            counts[key] = int(keyIds.size)

        total = sum(counts)
        offsets = np.zeros(WWMIShapeKeySlots, dtype = "<u4")
        running = 0
        for key in range(WWMIShapeKeySlots):
            offsets[key] = running
            running += counts[key]

        vertexIds = np.concatenate(ids).astype("<u4") if (ids) else np.zeros(0, dtype = "<u4")
        six = np.zeros((total, 6), dtype = "<f2")
        if (total):
            six[:, :3] = np.concatenate(deltas)

        return WWMIShapeKeys(offsets, vertexIds, six, counts)

    def generate(self, assetsFolder: str, modFolder: str, name: Optional[str] = None) -> WWMIIdentityMod:
        """
        Generates the identity mod of a character

        Parameters
        ----------
        assetsFolder: :class:`str`
            The character's asset folder

        modFolder: :class:`str`
            The folder to write the mod into. It is created if it does not exist

        name: Optional[:class:`str`]
            The name of the character in the mod. If this value is ``None``, the name of ``assetsFolder`` is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        Raises
        ------
        :class:`BadAssetData`
            If the asset folder is missing a file, or its data does not agree with itself

        :class:`UnknownDXGIFormat`
            If a component's ``.fmt`` declares a format that cannot be decoded

        Returns
        -------
        :class:`WWMIIdentityMod`
            The mod generated
        """

        if (name is None):
            name = os.path.basename(os.path.normpath(assetsFolder))

        mesh = self.buildMesh(assetsFolder)
        textures = []
        if (self.includeTextures):
            textures = [(os.path.join(assetsFolder, fileName), fileName, textureHash) for fileName, textureHash in self.getTextures(assetsFolder)]
        return self._write(name, modFolder, mesh, textures)

    def buildMesh(self, assetsFolder: str) -> WWMIMesh:
        """
        Builds the buffers of a character's identity mod from its asset folder

        Parameters
        ----------
        assetsFolder: :class:`str`
            The character's asset folder

        Raises
        ------
        :class:`BadAssetData`
            If the asset folder is missing a file, or its data does not agree with itself

        :class:`UnknownDXGIFormat`
            If a component's ``.fmt`` declares a format that cannot be decoded

        Returns
        -------
        :class:`WWMIMesh`
            The mesh
        """

        self.print("log", f"Reading the asset folder {assetsFolder}")
        metadata = self.readMetadata(assetsFolder)
        components = self.readComponents(assetsFolder, metadata)
        for key in ("vb0_hash", "cb4_hash"):
            if (key not in metadata):
                raise BadAssetData(f"'{assetsFolder}': Metadata.json has no '{key}'")

        buffers: Dict[WWMIBuffers, bytes] = {}
        index = self.buildIndex(components)
        buffers[WWMIBuffers.Index] = index.tobytes()

        for buffer in (WWMIBuffers.Position, WWMIBuffers.Vector, WWMIBuffers.Color, WWMIBuffers.TexCoord):
            buffers[buffer] = self.buildVertexBuffer(components, self.getExportSemantics(metadata, buffer))

        blendSemantics = self.getExportSemantics(metadata, WWMIBuffers.Blend)
        blend, boneIds, weights = self.buildBlend(components, blendSemantics)
        buffers[WWMIBuffers.Blend] = blend
        blendStride = sum(stride for _, _, _, stride in blendSemantics)

        remaps, forward, reverse = self.buildBlendRemaps(components, boneIds, weights, index)
        if (remaps):
            buffers[WWMIBuffers.BlendRemapVertexVG] = boneIds.astype("<u2").tobytes()
            buffers[WWMIBuffers.BlendRemapForward] = forward.tobytes()
            buffers[WWMIBuffers.BlendRemapReverse] = reverse.tobytes()

        shapeKeys = self.buildShapeKeys(components)
        buffers[WWMIBuffers.ShapeKeyOffset] = shapeKeys.offsets.tobytes()
        buffers[WWMIBuffers.ShapeKeyVertexId] = shapeKeys.vertexIds.tobytes()
        buffers[WWMIBuffers.ShapeKeyVertexOffset] = shapeKeys.deltas.tobytes()

        return WWMIMesh(metadata, components, buffers, shapeKeys, remaps, blendStride, int(boneIds.shape[1]), int(boneIds.max()))

    @classmethod
    def getTextures(cls, assetsFolder: str) -> List[Tuple[str, str]]:
        """
        Retrieves the textures of an asset folder (every ``Components-<components> t=<hash>.dds``)

        Parameters
        ----------
        assetsFolder: :class:`str`
            The asset folder

        Returns
        -------
        List[Tuple[:class:`str`, :class:`str`]]
            The file name of each texture and the hash the game binds it under (lowercase), in file name order
        """

        textures = []
        for fileName in sorted(os.listdir(assetsFolder)):
            match = WWMITexturePattern.match(fileName)
            if (match is not None):
                textures.append((fileName, match.group("hash").lower()))
        return textures

    def generateFromRepo(self, name: str, modFolder: str, version: Optional[str] = None, downloader: Optional[ModDownloader] = None,
                         downloadFolder: Optional[str] = None, modName: Optional[str] = None) -> WWMIIdentityMod:
        """
        Generates the identity mod of a character from its download folder, downloaded from the repositories
        of :class:`ModDownloadRepos`, so no asset folder is needed

        Parameters
        ----------
        name: :class:`str`
            The character's name (see :meth:`ModDownloader.getName`)

        modFolder: :class:`str`
            The folder to write the mod into. It is created if it does not exist

        version: Optional[:class:`str`]
            The game version wanted (eg. ``4.0``). If this value is ``None``, the newest download folder is used (see :meth:`ModDownloader.find`) :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        downloader: Optional[:class:`ModDownloader`]
            What downloads the files (eg. one given local copies of the repositories). If this value is ``None``, every file is downloaded :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        downloadFolder: Optional[:class:`str`]
            The folder to keep the downloaded files in. If this value is ``None``, they are downloaded into a temporary folder that is deleted afterwards :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        modName: Optional[:class:`str`]
            The name of the character in the mod. If this value is ``None``, the prefix of the download folder's files is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        Raises
        ------
        :class:`Error`
            If no character has that name, or ``version`` is not a game version

        :class:`DownloadFailed`
            If a file cannot be downloaded

        :class:`BadAssetData`
            If the downloaded files do not agree with each other

        Returns
        -------
        :class:`WWMIIdentityMod`
            The mod generated
        """

        downloader = ModDownloader(logger = self.logger) if (downloader is None) else downloader
        download = downloader.find(ModLoaders.WWMI, name, version)

        with tempfile.TemporaryDirectory() as temp:
            downloader.download(download, temp if (downloadFolder is None) else downloadFolder)
            return self.generateFromDownload(download.folder, modFolder, download.prefix, name = modName)

    def generateFromDownload(self, downloadFolder: str, modFolder: str, prefix: str, name: Optional[str] = None) -> WWMIIdentityMod:
        """
        Generates the identity mod of a character from its download folder, laid out as Anime Game Remap's
        ``Data/Mod Downloads/WuWa/<Name>/<version>`` folders are:

        - ``<prefix>Metadata.json``: the asset folder's ``Metadata.json``
        - ``<prefix><buffer>.buf``: the buffers of the identity mod's ``Meshes`` folder (with ``Texcoord`` for ``TexCoord``)
        - ``<prefix>Texture<hash>.dds``: the textures

        :class:`WWMIDownloadFolderBuilder` writes such a folder from an asset folder.

        .. note::
            The mod's textures keep their download folder names (``<prefix>Texture<hash>.dds``), since the
            asset folder's names cannot be rebuilt from the download folder. That changes only the
            textures' file names and the order of their sections in ``mod.ini``.

        Parameters
        ----------
        downloadFolder: :class:`str`
            The download folder

        modFolder: :class:`str`
            The folder to write the mod into. It is created if it does not exist

        prefix: :class:`str`
            What the names of the download folder's files start with

        name: Optional[:class:`str`]
            The name of the character in the mod. If this value is ``None``, ``prefix`` is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        Raises
        ------
        :class:`BadAssetData`
            If the download folder is missing a file, or its data does not agree with itself

        Returns
        -------
        :class:`WWMIIdentityMod`
            The mod generated
        """

        name = prefix if (name is None) else name
        mesh = self.readDownloadMesh(downloadFolder, prefix)

        textures = []
        if (self.includeTextures):
            pattern = re.compile(re.escape(prefix) + WWMIDownloadTextureSuffix.pattern)
            for fileName in sorted(os.listdir(downloadFolder)):
                match = pattern.fullmatch(fileName)
                if (match is not None):
                    textures.append((os.path.join(downloadFolder, fileName), fileName, match.group("hash").lower()))

        return self._write(name, modFolder, mesh, textures)

    def readDownloadMesh(self, downloadFolder: str, prefix: str) -> WWMIMesh:
        """
        Reads the buffers of a character's identity mod from its download folder

        Parameters
        ----------
        downloadFolder: :class:`str`
            The download folder

        prefix: :class:`str`
            What the names of the download folder's files start with

        Raises
        ------
        :class:`BadAssetData`
            If the download folder is missing a file, or its data does not agree with itself

        Returns
        -------
        :class:`WWMIMesh`
            The mesh
        """

        self.print("log", f"Reading the download folder {downloadFolder}")
        metadataPath = os.path.join(downloadFolder, f"{prefix}Metadata.json")
        if (not os.path.isfile(metadataPath)):
            raise BadAssetData(f"'{metadataPath}' is missing")

        with open(metadataPath, "r", encoding = FileEncodings.UTF8.value) as f:
            metadata = json.load(f)
        for key in ("vb0_hash", "cb4_hash"):
            if (key not in metadata):
                raise BadAssetData(f"'{metadataPath}' has no '{key}'")

        drawRanges = [WWMIDrawRange(i, entry) for i, entry in enumerate(metadata.get("components") or [])]
        self.checkDrawRanges(drawRanges, metadata, downloadFolder)
        vertexCount = sum(drawRange.vertexCount for drawRange in drawRanges)
        indexCount = sum(drawRange.indexCount for drawRange in drawRanges)

        buffers: Dict[WWMIBuffers, bytes] = {}
        for buffer in WWMIBuffers:
            path = os.path.join(downloadFolder, f"{prefix}{WWMIDownloadNames[buffer]}.buf")
            if (os.path.isfile(path)):
                with open(path, "rb") as f:
                    buffers[buffer] = f.read()
            elif (buffer not in WWMIBlendRemapBuffers):
                raise BadAssetData(f"'{path}' is missing")

        # every buffer's size, against the counts Metadata.json gives
        expectedSizes = {WWMIBuffers.Index: indexCount * 4}
        for buffer in (WWMIBuffers.Position, WWMIBuffers.Vector, WWMIBuffers.Color, WWMIBuffers.TexCoord, WWMIBuffers.Blend):
            expectedSizes[buffer] = vertexCount * sum(stride for _, _, _, stride in self.getExportSemantics(metadata, buffer))
        expectedSizes[WWMIBuffers.ShapeKeyOffset] = WWMIShapeKeySlots * 4
        for buffer, size in expectedSizes.items():
            if (len(buffers[buffer]) != size):
                raise BadAssetData(f"{prefix}{WWMIDownloadNames[buffer]}.buf is {len(buffers[buffer])} bytes, but Metadata.json makes it {size}")

        # the Blend buffer's bone ids (truncated to 8 bits past 255) and weights
        blendSemantics = self.getExportSemantics(metadata, WWMIBuffers.Blend)
        blendStride = sum(stride for _, _, _, stride in blendSemantics)
        rows = np.frombuffer(buffers[WWMIBuffers.Blend], dtype = np.uint8).reshape(vertexCount, blendStride)
        offset = 0
        ids = weights = None
        for semanticName, _, _, stride in blendSemantics:
            if (semanticName.upper() == "BLENDINDICES"):
                ids = rows[:, offset:offset + stride].astype(np.uint16)
            elif (semanticName.upper() == "BLENDWEIGHT"):
                weights = rows[:, offset:offset + stride]
            offset += stride
        if (ids is None or weights is None):
            raise BadAssetData("Metadata.json's export_format has no BLENDINDICES or no BLENDWEIGHT in its 'Blend' buffer")
        weightsPerVertex = ids.shape[1]

        # the full ids, when the merged skeleton needed a blend remap
        hasRemap = [buffer in buffers for buffer in WWMIBlendRemapBuffers]
        if (any(hasRemap) and not all(hasRemap)):
            raise BadAssetData(f"'{downloadFolder}' has only some of the blend remap buffers")

        if (all(hasRemap)):
            vertexVG = buffers[WWMIBuffers.BlendRemapVertexVG]
            if (len(vertexVG) != vertexCount * weightsPerVertex * 2):
                raise BadAssetData(f"{prefix}BlendRemapVertexVG.buf is {len(vertexVG)} bytes, not {weightsPerVertex} 16-bit bone ids for each of {vertexCount} vertices")
            ids = np.frombuffer(vertexVG, dtype = "<u2").reshape(vertexCount, weightsPerVertex)

        index = np.frombuffer(buffers[WWMIBuffers.Index], dtype = "<u4")
        remaps, forward, reverse = self.buildBlendRemaps(drawRanges, ids, weights, index)
        remapsAgree = (forward.tobytes() == buffers.get(WWMIBuffers.BlendRemapForward) and reverse.tobytes() == buffers.get(WWMIBuffers.BlendRemapReverse)) if (remaps) else (not any(hasRemap))
        if (not remapsAgree):
            raise BadAssetData(f"'{downloadFolder}': the blend remap buffers do not match the blend remaps its Blend and Index buffers need")

        offsets = np.frombuffer(buffers[WWMIBuffers.ShapeKeyOffset], dtype = "<u4")
        vertexIds = np.frombuffer(buffers[WWMIBuffers.ShapeKeyVertexId], dtype = "<u4")
        deltas = np.frombuffer(buffers[WWMIBuffers.ShapeKeyVertexOffset], dtype = "<f2")
        if (deltas.size != vertexIds.size * 6):
            raise BadAssetData(f"{prefix}ShapeKeyVertexOffset.buf does not hold six 16-bit floats for each of the {vertexIds.size} shape key entries")

        ends = list(offsets[1:]) + [vertexIds.size]
        counts = [int(end) - int(start) for start, end in zip(offsets, ends)]
        shapeKeys = WWMIShapeKeys(offsets, vertexIds, deltas.reshape(-1, 6), counts)

        return WWMIMesh(metadata, drawRanges, buffers, shapeKeys, remaps, blendStride, weightsPerVertex, int(ids.max()) if (ids.size) else 0)

    def _write(self, name: str, modFolder: str, mesh: WWMIMesh, textures: List[Tuple[str, str, str]]) -> WWMIIdentityMod:
        self.print("log", f"Writing the mod into {modFolder}")
        meshes = os.path.join(modFolder, "Meshes")
        os.makedirs(meshes, exist_ok = True)

        # a blend remap left by an earlier run into the same folder would not match this mesh
        for buffer in WWMIBlendRemapBuffers:
            stalePath = os.path.join(meshes, buffer.value)
            if (buffer not in mesh.buffers and os.path.isfile(stalePath)):
                os.remove(stalePath)

        for buffer, data in mesh.buffers.items():
            with open(os.path.join(meshes, buffer.value), "wb") as f:
                f.write(data)

        textureList = []
        if (textures):
            textureFolder = os.path.join(modFolder, "Textures")
            os.makedirs(textureFolder, exist_ok = True)
            for src, fileName, textureHash in textures:
                shutil.copy2(src, os.path.join(textureFolder, fileName))
                textureList.append((fileName, textureHash))

        iniBuilder = WWMIIniBuilder(name, self.author, mesh.metadata, mesh.drawRanges, mesh.shapeKeys.entryCount, textureList,
                                    blendStride = mesh.blendStride, blendRemaps = mesh.blendRemaps, weightsPerVertex = mesh.weightsPerVertex)
        with open(os.path.join(modFolder, "mod.ini"), "w", encoding = FileEncodings.UTF8.value, newline = "\r\n") as f:
            f.write(iniBuilder.build())

        return WWMIIdentityMod(name, modFolder, mesh.metadata, mesh.drawRanges, mesh.shapeKeys, mesh.blendRemaps, mesh.weightsPerVertex, mesh.blendStride,
                               mesh.highestBone, {buffer: len(data) for buffer, data in mesh.buffers.items()}, textureList)


class IDModGenService(Model):
    """
    The library's entry point: generates the identity mods of several characters at once, from their asset
    folders or from their download folders, and reports what it did

    It is the model half, with no user interface of its own: progress and the summary go to the
    :attr:`logger` (nothing is reported without one), and the results are in :attr:`stats`. A character that
    cannot be generated does not stop the others: its exception is recorded in :attr:`IDModGenStats.skipped`.

    .. note::
        Like Anime Game Remap's ``RemapService``, :meth:`generate` returns nothing; read :attr:`stats` after it.
        For one character, a generator (:class:`GIMIIdentityModGenerator` or :class:`WWMIIdentityModGenerator`)
        can be used directly instead, and raises when it fails.

    Examples
    --------
    .. code-block:: python
        :linenos:

        import AGIDMGen as IDMG
        import FixRaidenBoss2 as FRB          # Anime Game Remap's API: its logger serves both libraries

        # every character's newest download folder, printed as it goes
        service = IDMG.IDModGenService(IDMG.ModLoaders.GIMI, names = ["Yelan", "Ayaka"], outputFolder = "Mods", logger = FRB.Logger())
        service.generate()
        print(sorted(service.stats.generated), service.stats.skipped)

        # from asset folders, collecting the output instead of printing it (eg. in a server)
        logger = FRB.Logger(logTxt = True, verbose = False)
        service = IDMG.IDModGenService(IDMG.ModLoaders.WWMI, assetsFolders = ["WWMI-Assets/PlayerCharacterData/Sanhua"], logger = logger)
        service.generate()
        print(logger.loggedTxt)

    Parameters
    ----------
    loader: :class:`ModLoaders`
        The mod loader the mods are for

    assetsFolders: Optional[List[:class:`str`]]
        The characters' asset folders to generate from. If this value is ``None``, no asset folder is used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    names: Optional[List[:class:`str`]]
        The characters to generate from their download folders (see :meth:`ModDownloader.getName`). If this value is ``None``, no download folder is used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    outputFolder: Optional[:class:`str`]
        The folder each mod is written into, as ``<outputFolder>/<name>``. If this value is ``None``, the current folder is used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    version: Optional[:class:`str`]
        The game version wanted for the download folders (see :meth:`ModDownloader.find`). If this value is ``None``, the newest :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    downloader: Optional[:class:`ModDownloader`]
        What downloads the download folders. If this value is ``None``, one that downloads every file :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    downloadFolder: Optional[:class:`str`]
        The folder to keep the downloaded files in, as ``<downloadFolder>/<name>``. If this value is ``None``, temporary folders are used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    generator: Optional[Union[:class:`GIMIIdentityModGenerator`, :class:`WWMIIdentityModGenerator`]]
        The generator, with its options. If this value is ``None``, one for ``loader`` with its default options :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    modName: Optional[:class:`str`]
        The name of the character in the mod, when there is only one character. If this value is ``None``, the generator's default :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    assetPrefix: Optional[:class:`str`]
        What a GIMI asset folder's files start with, when there is only one asset folder (see :meth:`GIMIIdentityModGenerator.generate`) :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    handleExceptions: :class:`bool`
        Whether a failure of the whole run (eg. options that contradict each other) is reported to the logger and :meth:`generate` returns, rather than raised :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``False``

    logger: Optional[:class:`BaseLogger`]
        Where the run reports progress. If this value is ``None``, nothing is reported :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Attributes
    ----------
    loader: :class:`ModLoaders`
        The mod loader the mods are for

    assetsFolders: List[:class:`str`]
        The characters' asset folders to generate from

    names: List[:class:`str`]
        The characters to generate from their download folders

    outputFolder: :class:`str`
        The folder each mod is written into

    version: Optional[:class:`str`]
        The game version wanted for the download folders

    downloader: :class:`ModDownloader`
        What downloads the download folders

    downloadFolder: Optional[:class:`str`]
        The folder to keep the downloaded files in

    generator: Union[:class:`GIMIIdentityModGenerator`, :class:`WWMIIdentityModGenerator`]
        The generator

    modName: Optional[:class:`str`]
        The name of the character in the mod, when there is only one character

    assetPrefix: Optional[:class:`str`]
        What a GIMI asset folder's files start with, when there is only one asset folder

    handleExceptions: :class:`bool`
        Whether a failure of the whole run is reported rather than raised
    """

    def __init__(self, loader: ModLoaders, assetsFolders: Optional[List[str]] = None, names: Optional[List[str]] = None, outputFolder: Optional[str] = None,
                 version: Optional[str] = None, downloader: Optional[ModDownloader] = None, downloadFolder: Optional[str] = None,
                 generator: Optional[Union[GIMIIdentityModGenerator, WWMIIdentityModGenerator]] = None, modName: Optional[str] = None,
                 assetPrefix: Optional[str] = None, handleExceptions: bool = False, logger: Optional[BaseLogger] = None):
        super().__init__(logger = logger)
        self.loader = loader
        self.assetsFolders = [] if (assetsFolders is None) else list(assetsFolders)
        self.names = [] if (names is None) else list(names)
        self.outputFolder = os.getcwd() if (outputFolder is None) else outputFolder
        self.version = version
        self.downloader = ModDownloader(logger = logger) if (downloader is None) else downloader
        self.downloadFolder = downloadFolder
        self.generator = generator
        self.modName = modName
        self.assetPrefix = assetPrefix
        self.handleExceptions = handleExceptions
        self._stats = IDModGenStats()

    @property
    def stats(self) -> IDModGenStats:
        """
        What the last :meth:`generate` did

        :getter: Retrieves the stats
        :type: :class:`IDModGenStats`
        """

        return self._stats

    def _getGenerator(self) -> Union[GIMIIdentityModGenerator, WWMIIdentityModGenerator]:
        expected = GIMIIdentityModGenerator if (self.loader == ModLoaders.GIMI) else WWMIIdentityModGenerator
        if (self.generator is None):
            return expected(logger = self.logger)
        if (not isinstance(self.generator, expected)):
            raise Error(f"a {type(self.generator).__name__} cannot generate {self.loader.value} mods")
        if (self.generator.logger is None):
            self.generator.logger = self.logger
        return self.generator

    def _checkOptions(self):
        sourceCount = len(self.assetsFolders) + len(self.names)
        if (sourceCount == 0):
            raise Error("there is nothing to generate: give asset folders or character names")
        if (self.modName is not None and sourceCount > 1):
            raise Error("a mod name can only be given for one character")
        if (self.assetPrefix is not None and (len(self.assetsFolders) != 1 or self.names)):
            raise Error("an asset prefix can only be given for one asset folder")
        if (self.assetPrefix is not None and self.loader != ModLoaders.GIMI):
            raise Error("an asset prefix is only for GIMI asset folders")

    def _reportException(self, error: BaseException):
        # the library's own errors explain themselves; anything else is a bug, and gets its traceback
        if (isinstance(error, Error)):
            self.print("error", str(error))
        else:
            self.print("handleException", error)

    def _generateOne(self, generator, label: str, generate) -> Optional[Any]:
        self.print("openHeading", label, sideLen = 5)
        try:
            mod = generate()
        except Exception as e:
            self._stats.addSkipped(label, e)
            self._reportException(e)
            self.print("closeHeading")
            return None

        self._stats.addGenerated(label, mod)
        for line in mod.getSummary():
            self.print("log", line)
        self.print("closeHeading")
        self.print("space")
        return mod

    def generate(self):
        """
        Generates the identity mods, then reports what was done

        Raises
        ------
        :class:`Error`
            If the options contradict each other, and :attr:`handleExceptions` is ``False``
        """

        self._stats.clear()
        try:
            self._checkOptions()
            generator = self._getGenerator()
        except Exception as e:
            if (not self.handleExceptions):
                raise
            self._reportException(e)
            return

        prevPrefix = None if (self.logger is None) else self.logger.prefix
        for assetsFolder in self.assetsFolders:
            label = os.path.basename(os.path.normpath(assetsFolder))
            if (self.logger is not None):
                self.logger.prefix = label

            kwargs = {"name": self.modName}
            if (self.loader == ModLoaders.GIMI):
                kwargs["assetPrefix"] = self.assetPrefix
            modFolder = os.path.join(self.outputFolder, self.modName if (self.modName is not None) else label)
            self._generateOne(generator, label, lambda: generator.generate(assetsFolder, modFolder, **kwargs))

        for name in self.names:
            if (self.logger is not None):
                self.logger.prefix = name

            modFolder = os.path.join(self.outputFolder, self.modName if (self.modName is not None) else name)
            downloadFolder = None if (self.downloadFolder is None) else os.path.join(self.downloadFolder, name)
            self._generateOne(generator, name, lambda: generator.generateFromRepo(name, modFolder, version = self.version, downloader = self.downloader,
                                                                                  downloadFolder = downloadFolder, modName = self.modName))

        if (self.logger is not None):
            self.logger.prefix = prevPrefix
        self.report()

    def report(self):
        """
        Reports the summary of the last :meth:`generate` to the logger
        """

        if (self.logger is None):
            return

        includePrefix = self.logger.includePrefix
        self.logger.includePrefix = False
        self.print("openHeading", "Summary", sideLen = 10)
        self.print("log", f"Generated {len(self._stats.generated)} identity mod(s) into {self.outputFolder}")
        if (self._stats.skipped):
            self.print("log", f"Could not generate {len(self._stats.skipped)}:")
            for name, error in self._stats.skipped.items():
                self.print("bulletPoint", f"{name}: {error}")
        self.print("closeHeading")

        if (self._stats.noErrors):
            self.print("space")
            self.print("log", "ENJOY")
        self.logger.includePrefix = includePrefix


class GIMIDownloadFolderBuilder():
    """
    Writes a GI character's download folder from its asset folder, laid out as Anime Game
    Remap's ``Data/Mod Downloads/GI/<Name>/<version>`` folders are (the same files Anime Game Remap's
    ``giDownloadFolder.py`` writes), plus a copy of the asset folder's ``hash.json``:

    - ``<name><component>Position.buf``, ``Blend.buf`` and ``Texcoord.buf``: each skinned component's vertex buffer, split as GIMI lays it out
    - ``<name><component><object>.ib``: each object's indices, as ``R32_UINT``
    - ``<name><component><object><kind>.dds``: every texture ``hash.json`` lists, and ``<name>Face<kind>.dds`` for the face's
    - ``<name>Hash.json``: the asset folder's ``hash.json``

    The asset folder's files are found by how their names END, so their prefix does not have to be the
    folder's name.

    :meth:`GIMIIdentityModGenerator.generateFromDownload` generates the identity mod from such a folder.

    Attributes
    ----------
    notes: List[:class:`str`]
        What the last :meth:`build` left out, and why (eg. an unskinned component, or a texture the asset folder does not have)
    """

    def __init__(self):
        self.notes: List[str] = []

    @classmethod
    def findOne(cls, folder: str, suffix: str, required: bool = True) -> Optional[str]:
        """
        Retrieves the file of a folder whose name ends with some text

        .. note::
            A longer name can end with the same text (``FooBodyDiffuse.dds`` and ``FooBangBodyDiffuse.dds``),
            so the shortest name is taken, and two shortest names of the same length are an error.

        Parameters
        ----------
        folder: :class:`str`
            The folder

        suffix: :class:`str`
            What the file's name ends with

        required: :class:`bool`
            Whether a missing file is an error :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``True``

        Raises
        ------
        :class:`BadAssetData`
            If several files are equally short, or no file matches and ``required`` is ``True``

        Returns
        -------
        Optional[:class:`str`]
            The path to the file, or ``None`` if no file matches
        """

        hits = sorted(glob.glob(os.path.join(glob.escape(folder), "*" + suffix)))
        hits.sort(key = lambda path: len(os.path.basename(path)))
        if (not hits):
            if (required):
                raise BadAssetData(f"no asset file ends in {suffix!r}")
            return None

        if (len(hits) > 1 and len(os.path.basename(hits[0])) == len(os.path.basename(hits[1]))):
            raise BadAssetData(f"several asset files end in {suffix!r}: {', '.join(os.path.basename(hit) for hit in hits)}")
        return hits[0]

    def build(self, assetsFolder: str, downloadFolder: str, name: str) -> List[str]:
        """
        Writes the download folder

        Parameters
        ----------
        assetsFolder: :class:`str`
            The character's asset folder

        downloadFolder: :class:`str`
            The folder to write. It is created if it does not exist

        name: :class:`str`
            What the names of the download folder's files start with

        Raises
        ------
        :class:`BadAssetData`
            If the asset folder is missing a file, or its data does not agree with itself

        Returns
        -------
        List[:class:`str`]
            The names of the files written. What was left out is in :attr:`notes`
        """

        self.notes = []
        hashes = GIMIIdentityModGenerator.readHashes(assetsFolder)

        # ---- read everything before writing anything ----
        files: List[Tuple[str, bytes]] = []
        copies: List[Tuple[str, str]] = []

        for entry in hashes:
            comp = entry.get("component_name", "")
            objects = list(entry.get("object_classifications", []))

            if (entry.get("position_vb") and entry.get("blend_vb")):
                vbPath = self.findOne(assetsFolder, f"{comp}{objects[0]}-vb0={entry['position_vb']}.txt")
                vbDump = VbDumpFile.read(vbPath)
                if (vbDump is None):
                    raise BadAssetData(f"{os.path.basename(vbPath)}: its header's elements cannot be read")

                buffers, _ = GIMIIdentityModGenerator.buildBuffers(vbDump, os.path.basename(vbPath))
                for buffer, data in buffers.items():
                    files.append((f"{name}{comp}{buffer.value}.buf", data))

                for obj in objects:
                    ib = IbDumpFile.read(self.findOne(assetsFolder, f"{comp}{obj}-ib={entry['ib']}.txt")).indices
                    if (ib.size and int(ib.max()) >= vbDump.vertexCount):
                        raise BadAssetData(f"{comp}{obj}: index {int(ib.max())} beyond the {vbDump.vertexCount} vertices")
                    files.append((f"{name}{comp}{obj}.ib", ib.astype("<u4").tobytes()))

            elif (entry.get("position_vb")):
                missing = ["blend_vb"] + ([] if entry.get("root_vs") else ["root_vs"])
                self.notes.append(f"unskinned component {comp!r} (objects {', '.join(objects)}): no buffers written -- hash.json has no {', '.join(missing)}")

            for obj, textureList in zip(objects, entry.get("texture_hashes", [])):
                if (not textureList and entry.get("position_vb")):
                    self.notes.append(f"component {comp!r} object {obj!r}: hash.json lists NO textures")

                for kind, ext, _ in textureList:
                    if (ext.lower() != ".dds"):
                        continue

                    suffix, dst = (f"Face{obj}{kind}{ext}", f"{name}Face{kind}{ext}") if (comp == "Face") else (f"{comp}{obj}{kind}{ext}", f"{name}{comp}{obj}{kind}{ext}")
                    src = self.findOne(assetsFolder, suffix, required = False)
                    if (src is None):
                        self.notes.append(f"missing texture: *{suffix} (hash.json lists it, the asset folder has no file)")
                    else:
                        copies.append((src, dst))

        with open(os.path.join(assetsFolder, "hash.json"), "rb") as f:
            files.append((f"{name}{GIMIHashFileSuffix}", f.read()))

        # ---- write the folder ----
        os.makedirs(downloadFolder, exist_ok = True)
        written = []
        for fileName, data in files:
            with open(os.path.join(downloadFolder, fileName), "wb") as f:
                f.write(data)
            written.append(fileName)

        for src, dst in copies:
            shutil.copyfile(src, os.path.join(downloadFolder, dst))
            written.append(dst)

        return written


class WWMIDownloadFolderBuilder():
    """
    Writes a WuWa character's download folder from its asset folder, laid out as Anime Game
    Remap's ``Data/Mod Downloads/WuWa/<Name>/<version>`` folders are (the same files Anime Game Remap's
    ``wwmiDownloadFolder.py`` writes):

    - ``<name><buffer>.buf``: the buffers of the character's identity mod, with ``Texcoord`` for ``TexCoord``
    - ``<name>Texture<hash>.dds``: every texture of the asset folder
    - ``<name>Metadata.json`` and ``<name>TextureUsage.json``: the asset folder's manifests

    :meth:`WWMIIdentityModGenerator.generateFromDownload` generates the identity mod from such a folder.

    Parameters
    ----------
    generator: Optional[:class:`WWMIIdentityModGenerator`]
        What builds the buffers. If this value is ``None``, a generator with its default options is used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Attributes
    ----------
    generator: :class:`WWMIIdentityModGenerator`
        What builds the buffers
    """

    def __init__(self, generator: Optional[WWMIIdentityModGenerator] = None):
        self.generator = WWMIIdentityModGenerator() if (generator is None) else generator

    def build(self, assetsFolder: str, downloadFolder: str, name: str, texturesFrom: Optional[str] = None) -> List[str]:
        """
        Writes the download folder

        Parameters
        ----------
        assetsFolder: :class:`str`
            The character's asset folder

        downloadFolder: :class:`str`
            The folder to write. It is created if it does not exist

        name: :class:`str`
            What the names of the download folder's files start with

        texturesFrom: Optional[:class:`str`]
            Another asset folder of the same character to take the textures and ``TextureUsage.json`` from (eg. a second frame dump, taken at a higher texture detail). If this value is ``None``, ``assetsFolder`` is used :raw-html:`<br />` :raw-html:`<br />`

            **Default**: ``None``

        Raises
        ------
        :class:`BadAssetData`
            If the asset folder is missing a file, or its data does not agree with itself

        Returns
        -------
        List[:class:`str`]
            The names of the files written
        """

        textureSource = assetsFolder if (texturesFrom is None) else texturesFrom
        mesh = self.generator.buildMesh(assetsFolder)

        manifests = [(os.path.join(assetsFolder, "Metadata.json"), f"{name}Metadata.json"),
                     (os.path.join(textureSource, "TextureUsage.json"), f"{name}TextureUsage.json")]
        for src, _ in manifests:
            if (not os.path.isfile(src)):
                raise BadAssetData(f"'{src}' is missing")

        os.makedirs(downloadFolder, exist_ok = True)
        written = []
        for buffer, data in mesh.buffers.items():
            fileName = f"{name}{WWMIDownloadNames[buffer]}.buf"
            with open(os.path.join(downloadFolder, fileName), "wb") as f:
                f.write(data)
            written.append(fileName)

        for src, fileName in manifests:
            shutil.copyfile(src, os.path.join(downloadFolder, fileName))
            written.append(fileName)

        for fileName, textureHash in self.generator.getTextures(textureSource):
            dst = f"{name}Texture{textureHash}.dds"
            shutil.copyfile(os.path.join(textureSource, fileName), os.path.join(downloadFolder, dst))
            written.append(dst)

        return written


#: The name of the log file the command line writes with ``--log``
LogFileName = "IDModGenLog.txt"

#: Where the names of the characters that can be made are listed, for a run that asks for them
CharacterListLink = "https://github.com/Alex-Au1/Anime-Game-Identity-Mod-Generator/blob/main/Mods/README.md"


def makeArgParser() -> argparse.ArgumentParser:
    """
    Builds the command line's argument parser

    Returns
    -------
    :class:`argparse.ArgumentParser`
        The parser
    """

    parser = argparse.ArgumentParser(prog = "AGIDMGen", description = "Generates the identity mods of characters: the game's own models, written out as mods")
    loaders = parser.add_subparsers(dest = "loader", required = True)

    wwmi = loaders.add_parser(ModLoaders.WWMI.value.lower(), aliases = [ModLoaders.WWMI.value], help = "WuWa characters, from WWMI-Assets folders or download folders")
    wwmi.add_argument("sources", nargs = "*", help = "the asset folders (Metadata.json, Component N.fmt/.vb/.ib, *.dds), or with --download the characters' names")
    wwmi.add_argument("--author", default = "Anime Game Remap", help = "the mod author WWMI shows")
    wwmi.add_argument("--noTextures", action = "store_true", help = "leave the textures out (geometry, skeleton and shape keys only)")
    wwmi.add_argument("--rawBones", action = "store_true", help = "write bone indices as vg_offset + local instead of through the vg_map (the merged skeleton's duplicate slots; every real mod uses the vg_map)")

    gimi = loaders.add_parser(ModLoaders.GIMI.value.lower(), aliases = [ModLoaders.GIMI.value], help = "GI characters, from GI-Model-Importer-Assets folders or download folders")
    gimi.add_argument("sources", nargs = "*", help = "the asset folders (hash.json, *-vb0=*.txt, *-ib=*.txt, *.dds), or with --download the characters' names")
    gimi.add_argument("--assetPrefix", default = None, help = "what the asset folder's files start with, when that is not the folder's name (one asset folder only)")
    gimi.add_argument("--noFix", action = "store_true", help = "leave the ORFix / NNFix run lines out of the object sections")
    gimi.add_argument("--faceRegister", default = "ps-t0", help = "the register the face diffuse is bound to (GI 6.x swapped it to ps-t1 on some skins; default ps-t0)")
    gimi.add_argument("--textureFrom", action = "append", default = None, metavar = "COMP=COMP:OBJ[:LAYOUT]",
                      help = "a component with no textures of its own reads another component object's, in the borrower's own normalMap / plain layout (e.g. Bang=Body:A, Eye=Body:A:plain); repeatable")

    for subparser in (wwmi, gimi):
        subparser.add_argument("--out", default = None, help = "the folder each mod is written into, as <out>/<name> (default: the current folder)")
        subparser.add_argument("--name", default = None, help = "the character's name in the mod (one character only)")
        subparser.add_argument("--download", action = "store_true", help = "the sources are characters' names: generate from their download folders (from AG Remap's repository, then this library's)")
        subparser.add_argument("--all", action = "store_true", help = "with --download: every character that has a download folder")
        subparser.add_argument("--version", default = None, help = "with --download: the game version wanted, eg. 4.0 (default: the newest)")
        subparser.add_argument("--localData", action = "append", default = None, metavar = "REPO=FOLDER",
                               help = "with --download: copy a repository's files from a local copy of its 'Data/Mod Downloads' folder instead (REPO is AGRemap or AGIDMGen); repeatable")
        subparser.add_argument("--downloadFolder", default = None, help = "with --download: keep the downloaded files in <downloadFolder>/<name> (default: temporary folders)")
        subparser.add_argument("--proxy", default = None, help = "with --download: the proxy to download through")
        subparser.add_argument("--log", default = None, help = f"write everything printed into <log>/{LogFileName}")
        subparser.add_argument("--quiet", action = "store_true", help = "print only errors")

    return parser


def makeService(args: argparse.Namespace, logger: Logger) -> IDModGenService:
    """
    Builds the service the command line runs

    Parameters
    ----------
    args: :class:`argparse.Namespace`
        The parsed arguments, from :func:`makeArgParser`

    logger: :class:`Logger`
        Where the service reports what it does

    Raises
    ------
    :class:`Error`
        If the arguments are not valid

    Returns
    -------
    :class:`IDModGenService`
        The service
    """

    loader = ModLoaders.GIMI if (args.loader.upper() == ModLoaders.GIMI.value) else ModLoaders.WWMI
    if (loader == ModLoaders.GIMI):
        textureSources = dict(GIMITextureSource.parse(value) for value in (args.textureFrom or []))
        generator = GIMIIdentityModGenerator(includeFix = not args.noFix, faceRegister = args.faceRegister, textureSources = textureSources, logger = logger)
    else:
        generator = WWMIIdentityModGenerator(author = args.author, includeTextures = not args.noTextures, useVgMap = not args.rawBones, logger = logger)

    localFolders = {}
    for value in (args.localData or []):
        repo, separator, folder = value.partition("=")
        if (not separator or repo not in ModDownloadRepos.__members__):
            raise Error(f"--localData is REPO=FOLDER with REPO one of {', '.join(ModDownloadRepos.__members__)}, not {value!r}")
        localFolders[ModDownloadRepos[repo]] = folder

    if (args.all and not args.download):
        raise Error("--all is for --download")

    names = None
    assetsFolders = None
    if (args.download):
        names = ModDownloader.getCharacters(loader) if (args.all) else args.sources
    else:
        assetsFolders = args.sources

    return IDModGenService(loader, assetsFolders = assetsFolders, names = names, outputFolder = args.out, version = args.version,
                           downloader = ModDownloader(localFolders = localFolders, proxy = args.proxy, logger = logger), downloadFolder = args.downloadFolder,
                           generator = generator, modName = args.name, assetPrefix = getattr(args, "assetPrefix", None), handleExceptions = True, logger = logger)


def askArgs(logger: BaseLogger) -> List[str]:
    """
    Asks the user which game and which characters to make the identity mods of, for a run with no arguments
    (eg. the script double-clicked)

    :raw-html:`<br />`

    The mods are made from the characters' download folders, into the current folder

    Parameters
    ----------
    logger: :class:`BaseLogger`
        Where the questions are asked

    Returns
    -------
    List[:class:`str`]
        The arguments the answers stand for, eg. ``["gimi", "Yelan", "--download"]``
    """

    loaders = {loader.value.lower(): loader for loader in ModLoaders}
    loaderNames = {ModLoaders.GIMI: "GI", ModLoaders.WWMI: "WuWa"}
    loaderChoices = " or ".join(f"{name} ({loaderNames[loader]})" for name, loader in loaders.items())

    # the questions are shown without the logger's '# prefix -->', as BaseLogger.waitExit shows its own
    prevIncludePrefix = logger.includePrefix
    logger.includePrefix = False
    try:
        loader = None
        while (loader is None):
            loader = loaders.get(logger.input(f"Which game? Type {loaderChoices}: ").strip().lower())

        logger.log(f"\nThe characters' names are listed at {CharacterListLink}")
        names = []
        while (not names):
            names = logger.input("Which characters? Type their names with a space between each, or 'all' for every character: ").split()
        logger.log("")
    finally:
        logger.includePrefix = prevIncludePrefix

    if (len(names) == 1 and names[0].lower() == "all"):
        return [loader.value.lower(), "--download", "--all"]
    return [loader.value.lower()] + names + ["--download"]


def run(args: argparse.Namespace, logger: BaseLogger) -> int:
    """
    Makes the identity mods the parsed arguments ask for

    Parameters
    ----------
    args: :class:`argparse.Namespace`
        The parsed arguments, from :func:`makeArgParser`

    logger: :class:`BaseLogger`
        Where the service reports what it does

    Returns
    -------
    :class:`int`
        The exit code, as :func:`main` returns it
    """

    try:
        service = makeService(args, logger)
    except Error as e:
        logger.error(str(e))
        return 1

    service.generate()
    if (args.log is not None):
        os.makedirs(args.log, exist_ok = True)
        with open(os.path.join(args.log, LogFileName), "w", encoding = FileEncodings.UTF8.value) as f:
            f.write(logger.loggedTxt)

    stats = service.stats
    if (not stats.noErrors or not stats.generated):
        return 1
    if (any(getattr(mod, "checksumMatches", None) is False or getattr(mod, "dispatchYMatches", None) is False for mod in stats.generated.values())):
        return 2
    return 0


def main(argv: Optional[List[str]] = None, logger: Optional[BaseLogger] = None) -> int:
    """
    Runs the command line: ``python -m AGIDMGen <gimi|wwmi> SOURCE ... [--out FOLDER] [options]``

    :raw-html:`<br />`

    With no arguments (eg. the script double-clicked), asks which game and which characters to make the mods of
    (see :func:`askArgs`), then waits for ENTER before it ends, so the window stays open to be read

    Parameters
    ----------
    argv: Optional[List[:class:`str`]]
        The arguments, without the program name. If this value is ``None``, the arguments of the running program are used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    logger: Optional[:class:`BaseLogger`]
        Where everything is printed and asked. If this value is ``None``, a console :class:`Logger` is used :raw-html:`<br />` :raw-html:`<br />`

        **Default**: ``None``

    Returns
    -------
    :class:`int`
        The exit code: 0 when every mod was generated, 1 when one could not be (or the arguments are not valid), 2 when a WWMI mod's shape keys do not match its ``Metadata.json``
    """

    if (argv is None):
        argv = sys.argv[1:]

    interactive = not argv
    if (interactive):
        if (logger is None):
            logger = Logger()

        try:
            argv = askArgs(logger)
        except EOFError:
            return 1

    args = makeArgParser().parse_args(argv)
    if (logger is None):
        logger = Logger(logTxt = args.log is not None, verbose = not args.quiet)

    exitCode = run(args, logger)
    if (interactive):
        try:
            logger.waitExit()
        except EOFError:
            pass

    return exitCode

# Main Driver Code
if __name__ == "__main__":
    sys.exit(main())

